window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"胆囊结石首选的检查是？","options":["口服胆囊造影","CT","MRI","腹部超声"],"answer":3,"explanation":"超声对胆囊结石诊断准确率>95%，是首选检查。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2001","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆囊结石有症状者的首选治疗是？","options":["腹腔镜胆囊切除术","溶石治疗","观察","体外碎石"],"answer":0,"explanation":"有症状的胆囊结石首选腹腔镜胆囊切除术（LC），是金标准。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2002","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性胆囊炎的典型体征是？","options":["麦氏点压痛","Murphy征阳性","移动性浊音","肝掌"],"answer":1,"explanation":"急性胆囊炎：右上腹压痛、Murphy征阳性（深吸气时因疼痛而中止吸气）。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2003","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性梗阻性化脓性胆管炎（AOSC）的典型表现是？","options":["单纯发热","Charcot三联征","无痛性黄疸","Reynolds五联征（腹痛、寒战高热、黄疸、休克、神经中枢症状）"],"answer":3,"explanation":"AOSC（急性重症胆管炎）：Charcot三联征（腹痛、寒战高热、黄疸）+休克+神经中枢症状=Reynolds五联征。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2004","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"Charcot三联征是指？","options":["腹痛、呕吐、黄疸","腹痛、寒战高热、黄疸","发热、皮疹、关节痛","腹痛、腹泻、便血"],"answer":1,"explanation":"Charcot三联征提示胆管炎（胆管结石梗阻+感染）。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2005","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆道蛔虫病的典型表现是？","options":["发热为主","持续剧烈腹痛伴腹膜刺激征","无痛性黄疸","阵发性钻顶样绞痛（剑突下），症状重体征轻"],"answer":3,"explanation":"胆道蛔虫：剑突下阵发性钻顶样绞痛，间歇期如常人（症状与体征不符）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2006","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肠梗阻的典型表现是？","options":["腹泻","腹痛、呕吐、腹胀、停止排气排便（四大症状）","便血","发热"],"answer":1,"explanation":"肠梗阻四大症状：阵发性绞痛、呕吐、腹胀、停止排气排便。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2007","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"机械性肠梗阻与麻痹性肠梗阻的鉴别是？","options":["无区别","机械性肠鸣音消失","麻痹性肠鸣音亢进","机械性肠鸣音亢进（气过水声）；麻痹性肠鸣音消失"],"answer":3,"explanation":"机械性肠梗阻肠鸣音亢进（气过水声、金属音）；麻痹性（腹膜炎、术后）肠鸣音消失。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2008","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"绞窄性肠梗阻的特点是？","options":["阵发性绞痛（单纯）","腹痛持续剧烈、腹膜刺激征、血性腹水","呕吐轻","腹胀轻"],"answer":1,"explanation":"绞窄性肠梗阻有血运障碍：腹痛持续剧烈、腹膜刺激征、血性渗出、休克，需急诊手术。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2009","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肠梗阻的治疗原则是？","options":["口服泻药","立即手术（所有类型）","大量进食","禁食胃肠减压、纠正水电解质紊乱、解除梗阻"],"answer":3,"explanation":"肠梗阻基础治疗：禁食、胃肠减压、补液纠酸，单纯性可保守，绞窄性手术。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2010","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性乳腺炎最常见的病原菌是？","options":["链球菌","金黄色葡萄球菌","大肠埃希菌","厌氧菌"],"answer":1,"explanation":"急性乳腺炎（哺乳期）以金黄色葡萄球菌最常见，经乳头破损侵入。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2011","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性乳腺炎的好发人群是？","options":["青春期女性","老年女性","产后3-4周的初产妇","男性"],"answer":2,"explanation":"急性乳腺炎多见于产后3-4周初产妇，乳汁淤积+细菌侵入。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2012","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性乳腺炎形成脓肿后的处理是？","options":["切开引流（放射状切口）","继续哺乳","热敷","抗生素（唯一）"],"answer":0,"explanation":"乳腺脓肿需及时切开引流（放射状切口避免损伤乳管），患侧暂停哺乳。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2013","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌最常见的首发表现是？","options":["无痛性单发乳房肿块","乳头溢液","乳房疼痛","皮肤红肿"],"answer":0,"explanation":"乳腺癌多为无痛性单发肿块（质硬、边界不清、活动度差），多位于外上象限。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2014","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌酒窝征的机制是？","options":["皮肤感染","淋巴水肿","肿瘤侵犯乳房悬韧带（Cooper韧带）使其缩短","肿瘤直接侵犯皮肤"],"answer":2,"explanation":"肿瘤侵犯Cooper韧带使其缩短，牵拉皮肤凹陷形成酒窝征。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2015","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌橘皮样变的机制是？","options":["皮肤感染","Cooper韧带受侵","癌细胞堵塞皮下淋巴管，淋巴水肿","血管扩张"],"answer":2,"explanation":"癌细胞堵塞真皮淋巴管致淋巴水肿，毛囊凹陷，皮肤呈橘皮样。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2016","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌淋巴转移最常见的部位是？","options":["腹股沟","对侧腋窝","锁骨上（首先）","同侧腋窝淋巴结"],"answer":3,"explanation":"乳腺癌淋巴转移首先至同侧腋窝淋巴结。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2017","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌的确诊方法是？","options":["MRI","钼靶","超声","穿刺或切除活检（病理）"],"answer":3,"explanation":"乳腺癌确诊依赖病理（穿刺活检或切除活检），钼靶、超声为筛查手段。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2018","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌内分泌治疗适用于？","options":["三阴性乳腺癌","所有患者","HER2阳性者","雌激素受体（ER）或孕激素受体（PR）阳性者"],"answer":3,"explanation":"ER/PR阳性者行内分泌治疗（他莫昔芬、芳香化酶抑制剂），HER2阳性用靶向药。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2019","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺功能亢进症手术治疗的适应证不包括？","options":["中重度甲亢、腺体大","青少年患者（首选）","压迫症状","怀疑恶变"],"answer":1,"explanation":"青少年甲亢首选抗甲状腺药物；手术适用于腺体大、压迫症状、怀疑恶变、药物治疗无效或复发者。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2020","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺大部切除术最严重的并发症是？","options":["声音嘶哑","呼吸困难和窒息（出血压迫、喉头水肿）","手足抽搐","甲状腺危象"],"answer":1,"explanation":"术后48小时内呼吸困难和窒息（出血、喉头水肿、气管塌陷）最危急，需紧急处理。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2021","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺大部切除术后声音嘶哑提示？","options":["喉上神经外支损伤","喉上神经内支损伤","喉返神经损伤","甲状旁腺损伤"],"answer":2,"explanation":"喉返神经损伤致声音嘶哑（单侧）或失声、窒息（双侧）；喉上神经内支损伤致饮水呛咳。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2022","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺术后手足抽搐提示？","options":["喉返神经损伤","甲状旁腺损伤（低钙）","喉上神经损伤","出血"],"answer":1,"explanation":"甲状旁腺误伤致低钙血症，表现为手足抽搐，用葡萄糖酸钙治疗。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2023","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺癌最常见的类型是？","options":["髓样癌","滤泡状癌","乳头状癌","未分化癌"],"answer":2,"explanation":"甲状腺癌以乳头状癌最常见（约80-90%），生长慢、预后好。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2024","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折的专有体征是？","options":["疼痛、肿胀","畸形、异常活动、骨擦音（感）","功能障碍","淤血"],"answer":1,"explanation":"骨折三大专有体征：畸形、异常活动、骨擦音/骨擦感，具备其一即可确诊。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2025","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折急救的原则是？","options":["热敷","立即复位","立即手术","固定、止血、包扎、搬运（先救命后治伤）"],"answer":3,"explanation":"骨折急救：先处理休克和危及生命的损伤，妥善固定（不盲目复位），正确搬运。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2026","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折早期并发症不包括？","options":["坠积性肺炎（晚期）","休克","脂肪栓塞","骨筋膜室综合征"],"answer":0,"explanation":"坠积性肺炎为长期卧床的晚期并发症；早期并发症有休克、脂肪栓塞、骨筋膜室综合征、血管神经损伤。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2027","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨筋膜室综合征的典型表现是？","options":["活动自如","无痛","皮温升高（早期）","剧痛、被动牵拉痛、感觉异常、皮肤苍白（5P征）"],"answer":3,"explanation":"骨筋膜室综合征5P征：疼痛（pain）、苍白（pallor）、感觉异常（paresthesia）、麻痹（paralysis）、无脉（pulselessness），需紧急切开减压。","exam":"医疗编","__sub":"外科临床","diff":3,"id":"yl-2028","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折愈合血肿机化期的时间是？","options":["伤后1年","伤后2-3天","伤后2-3个月","伤后2-3周"],"answer":3,"explanation":"骨折愈合过程：血肿机化期（2-3周）→原始骨痂形成期（4-8周）→骨痂改造塑形期。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2029","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折临床愈合的标准不包括？","options":["局部仍有异常活动","局部无压痛、无纵向叩击痛","局部无异常活动","X线显示骨折线模糊、有连续性骨痂"],"answer":0,"explanation":"临床愈合标准：无压痛、无纵向叩痛、无异常活动、X线骨折线模糊有骨痂、功能恢复。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2030","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"Colles骨折（桡骨远端）的典型畸形是？","options":["垂腕","爪形手","餐叉样和枪刺样畸形","方肩"],"answer":2,"explanation":"Colles骨折（伸直型桡骨远端骨折）典型畸形为餐叉样和枪刺样畸形。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2031","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肩关节脱位的典型表现是？","options":["餐叉畸形","方肩畸形、Dugas征（搭肩试验）阳性","爪形手","下肢短缩"],"answer":1,"explanation":"肩关节前脱位：方肩畸形、关节盂空虚、Dugas征阳性（患侧手搭对侧肩部肘不能贴胸）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2032","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"髋关节脱位（后脱位）的典型畸形是？","options":["患肢屈曲、内收、内旋、短缩","外展外旋","伸直位","无畸形"],"answer":0,"explanation":"髋关节后脱位：患肢屈曲内收内旋短缩畸形，大转子向上移位。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2033","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰椎间盘突出症最常见的突出部位是？","options":["L4-5和L5-S1","L1-2","L2-3","L3-4"],"answer":0,"explanation":"腰椎间盘突出症最常见于L4-5和L5-S1间隙，压迫L5和S1神经根。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2034","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰椎间盘突出症的主要表现是？","options":["下肢无力（唯一）","单纯腰痛","腰痛伴坐骨神经痛（下肢放射痛）","大小便失禁（早期）"],"answer":2,"explanation":"典型表现：腰痛+坐骨神经痛（沿臀部、大腿后侧、小腿放射），直腿抬高试验阳性。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2035","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰椎间盘突出症最重要的体征是？","options":["Babinski征","Kernig征","直腿抬高试验及加强试验阳性","肌张力增高"],"answer":2,"explanation":"直腿抬高试验（<60°出现放射痛）及加强试验阳性是腰椎间盘突出症的重要体征。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2036","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"颈椎病最常见的类型是？","options":["椎动脉型","脊髓型","神经根型","交感神经型"],"answer":2,"explanation":"神经根型颈椎病最常见（50-60%），表现为颈肩痛伴上肢放射痛、麻木。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2037","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脊髓型颈椎病的特点是？","options":["单纯颈肩痛","下肢无力、踩棉花感、病理征阳性","头晕","耳鸣"],"answer":1,"explanation":"脊髓型颈椎病最严重：四肢无力、行走踩棉花感、腱反射亢进、病理征阳性，多需手术。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2038","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性血源性骨髓炎的好发部位是？","options":["脊柱","扁骨","长骨干骺端（胫骨上端、股骨下端）","颅骨"],"answer":2,"explanation":"急性血源性骨髓炎多见于儿童长骨干骺端（血流缓慢易滞留细菌）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2039","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性血源性骨髓炎早期诊断最有价值的检查是？","options":["局部穿刺抽脓（细菌培养）","X线（早期正常）","CT","MRI（早期敏感）"],"answer":0,"explanation":"发病早期X线无改变（2周后出现），局部穿刺抽脓+培养可早期确诊。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2040","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨肿瘤的好发年龄与部位是？","options":["婴幼儿颅骨","老年人扁骨","中年人脊柱（唯一）","青少年长骨干骺端（骨肉瘤）"],"answer":3,"explanation":"骨肉瘤好发于青少年长骨干骺端（股骨下端、胫骨上端），Codman三角和日光射线征为特征。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2041","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前列腺增生症最早出现的症状是？","options":["尿失禁","排尿困难","血尿","尿频（尤其夜尿增多）"],"answer":3,"explanation":"前列腺增生最早症状为尿频（夜尿增多），进行性排尿困难为最重要表现。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2042","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前列腺增生最重要的表现是？","options":["尿频","进行性排尿困难","血尿","尿潴留"],"answer":1,"explanation":"前列腺增生（老年男性）进行性排尿困难（排尿迟缓、尿线细、滴沥）为最重要症状。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2043","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前列腺增生急性尿潴留的处理是？","options":["立即手术","导尿（必要时留置）","热敷（唯一）","大量饮水"],"answer":1,"explanation":"急性尿潴留先导尿（必要时留置导尿管），择期处理增生。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2044","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"泌尿系结石的主要表现是？","options":["脓尿","无痛性血尿","肾绞痛伴血尿","蛋白尿"],"answer":2,"explanation":"泌尿系结石：肾绞痛（剧烈阵发性腰痛向下腹放射）伴血尿（镜下或肉眼）。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2045","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾绞痛发作时的紧急处理是？","options":["大量补液","立即手术","解痉止痛（阿托品/山莨菪碱+止痛药）","抗生素"],"answer":2,"explanation":"肾绞痛用解痉药（阿托品、山莨菪碱）+止痛药（哌替啶等），多饮水促排石。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2046","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输尿管结石直径小于多少可保守排石？","options":["0.6 cm","1.5 cm","2 cm","3 cm"],"answer":0,"explanation":"结石<0.6cm、光滑、无梗阻感染可保守治疗（多饮水、药物排石）；较大者体外碎石或手术。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2047","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"膀胱肿瘤最常见的表现是？","options":["脓尿","尿频尿急","排尿困难","无痛性肉眼血尿"],"answer":3,"explanation":"膀胱肿瘤典型表现为间歇性无痛性肉眼血尿（全程）。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2048","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾癌的典型三联征是？","options":["尿频、尿急、尿痛","发热、贫血、消瘦","蛋白尿、水肿、高血压","血尿、腰痛、肿块"],"answer":3,"explanation":"肾癌三联征：血尿（最常见）、腰痛、肿块，同时出现者已属晚期。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2049","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤创面感染最常见的病原菌是？","options":["铜绿假单胞菌和金黄色葡萄球菌","大肠埃希菌","厌氧菌","真菌"],"answer":0,"explanation":"烧伤创面感染以铜绿假单胞菌和金黄色葡萄球菌常见。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2050","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"挤压综合征的主要表现是？","options":["发热","单纯骨折","肢体肿胀、肌红蛋白尿、急性肾损伤","黄疸"],"answer":2,"explanation":"挤压综合征：肢体长时间受压，肌红蛋白尿（酱油色）致急性肾损伤，需碱化尿液。","exam":"医疗编","__sub":"外科临床","diff":3,"id":"yl-2051","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"外科感染的特点不包括？","options":["多数为混合感染","多为单一细菌感染","局部表现明显","常需外科处理"],"answer":1,"explanation":"外科感染多为混合感染（多种细菌），局部症状明显，常需手术引流。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2052","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"疖与痈的区别是？","options":["痈为单个毛囊感染","痈为多个相邻毛囊及其所属皮脂腺的感染","疖更严重","无区别"],"answer":1,"explanation":"疖为单个毛囊及皮脂腺感染；痈为多个相邻毛囊的感染，范围大、症状重。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2053","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"危险三角区疖肿挤压的危险是？","options":["淋巴结炎","局部化脓","引起海绵状静脉窦炎（颅内感染）","败血症（必然）"],"answer":2,"explanation":"面部危险三角区疖肿挤压可使细菌经静脉入颅，引起海绵状静脉窦炎，危及生命。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2054","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"丹毒的病原体是？","options":["大肠埃希菌","金黄色葡萄球菌","乙型溶血性链球菌","厌氧菌"],"answer":2,"explanation":"丹毒为皮肤网状淋巴管炎，由乙型溶血性链球菌引起，边界清楚、鲜红色。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2055","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"破伤风的潜伏期一般为？","options":["1天","6-12天","1个月以上（必然）","数小时"],"answer":1,"explanation":"破伤风潜伏期一般6-12天，潜伏期越短病情越重。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2056","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气胸的分类不包括？","options":["血气胸（分类之一，但非基本类型）","闭合性（单纯性）气胸","交通性（开放性）气胸","张力性（高压性）气胸"],"answer":0,"explanation":"自发性气胸分闭合性、交通性、张力性三类；张力性最危急。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2057","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"张力性气胸的紧急处理是？","options":["吸氧（唯一）","立即手术","观察","立即用粗针头于患侧锁骨中线第2肋间穿刺排气"],"answer":3,"explanation":"张力性气胸（胸膜腔压力持续升高）立即用粗针头在第2肋间锁骨中线穿刺排气减压。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2058","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸腔闭式引流的适应证不包括？","options":["中大量气胸、血胸","少量闭合性气胸（肺压缩<20%）","开放性气胸","张力性气胸"],"answer":1,"explanation":"肺压缩<20%的少量气胸可观察自行吸收，不需闭式引流。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2059","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸腔闭式引流管的放置位置（排气）是？","options":["患侧锁骨中线第2肋间","腋中线第6-8肋间（排液）","胸骨旁第4肋间","肩胛线第8肋间"],"answer":0,"explanation":"排气于锁骨中线第2肋间；排液于腋中线与腋后线之间第6-8肋间。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2060","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"女性外阴部最易发生炎症的部位是？","options":["卵巢","子宫","输卵管","阴道（前庭大腺等）"],"answer":3,"explanation":"外阴阴道炎症最常见（解剖特点：与外界相通、邻近肛门）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2061","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"成年女性子宫的正常位置是？","options":["前倾前屈位","后倾后屈位","水平位","后倾前屈位"],"answer":0,"explanation":"正常子宫位置为前倾前屈位，依靠韧带（圆韧带、阔韧带等）和盆底组织维持。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2062","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维持子宫正常位置的主要韧带中，防止子宫下垂的是？","options":["子宫圆韧带","子宫主韧带","子宫阔韧带","卵巢固有韧带"],"answer":1,"explanation":"主韧带（宫颈横韧带）固定宫颈水平位置、防止子宫下垂；圆韧带维持前倾，骶子宫韧带维持前屈。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2063","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"防止子宫下垂最重要的韧带是？","options":["卵巢固有韧带","圆韧带","阔韧带","子宫主韧带"],"answer":3,"explanation":"主韧带（宫颈横韧带）固定宫颈、防止子宫下垂，是维持子宫位置最重要的韧带。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2064","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"女性青春期的重要标志是？","options":["身高突增","乳房发育（第二性征最早）","阴毛出现","月经初潮"],"answer":3,"explanation":"月经初潮是女性青春期的重要标志（乳房发育为最早出现的第二性征）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2065","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"女性一生中排卵的次数约为？","options":["100个","400-500个","1000个","50个"],"answer":1,"explanation":"女性一生约排出400-500个成熟卵子（每月1个，约35年生育期）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2066","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"排卵一般发生在下次月经来潮前？","options":["7天","14天左右","21天","28天"],"answer":1,"explanation":"排卵发生在下次月经来潮前14天左右（黄体期固定为14天）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2067","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"月经血的特点是？","options":["黑色","鲜红色、易凝固","暗红色、不凝固（含纤溶酶）","白色"],"answer":2,"explanation":"月经血暗红色、不凝（子宫内膜纤溶酶溶解纤维蛋白），量约20-60ml。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2068","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常月经周期平均为？","options":["35天","21天","28天","14天"],"answer":2,"explanation":"正常月经周期21-35天，平均28天；经期2-8天，平均4-6天。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2069","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"卵巢的功能是？","options":["孕育胎儿","仅分泌激素","仅产生卵子","产生卵子和分泌性激素"],"answer":3,"explanation":"卵巢有生殖功能（排卵）和内分泌功能（分泌雌激素、孕激素等）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2070","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"雌激素的生理作用不包括？","options":["促进子宫内膜增生","使子宫内膜呈分泌期改变","促进第二性征发育","使宫颈黏液稀薄"],"answer":1,"explanation":"分泌期改变由孕激素引起；雌激素使内膜增生、宫颈黏液稀薄拉丝长。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2071","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"孕激素的生理作用是？","options":["促进乳腺管增生（雌激素）","促进子宫内膜增生","使宫颈黏液拉丝长","使增生期子宫内膜转变为分泌期"],"answer":3,"explanation":"孕激素使增生期内膜转为分泌期、宫颈黏液变稠、基础体温升高0.3-0.5℃。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2072","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"受精的部位是？","options":["卵巢","子宫腔","输卵管峡部","输卵管壶腹部"],"answer":3,"explanation":"精子与卵子在输卵管壶腹部受精。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2073","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"受精卵着床的时间是？","options":["受精后1天","受精后6-7天","受精后1个月","受精后14天"],"answer":1,"explanation":"受精卵在受精后6-7天着床（植入子宫内膜）。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2074","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠全过程分为？","options":["早期（20周前）","早期（16周前）、中期、晚期","早期（12周末前）、中期（13-27周末）、晚期（28周及以后）","早期（10周前）"],"answer":2,"explanation":"妊娠分期：12周末前为早期，13-27周末为中期，28周及以后为晚期。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2075","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠早期诊断最重要的表现是？","options":["停经（育龄妇女）","恶心呕吐","尿频","乳房胀痛"],"answer":0,"explanation":"育龄妇女停经是妊娠最早最重要的症状，结合早孕反应、尿HCG阳性可诊断。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2076","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"早孕反应一般出现在停经后？","options":["4周","2周","12周","6周左右"],"answer":3,"explanation":"早孕反应（恶心、呕吐、嗜睡等）多在停经6周左右出现，12周左右自行消失。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2077","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常胎心率为？","options":["110-160次/分","80-100次/分","160-180次/分","100-120次/分"],"answer":0,"explanation":"正常胎心110-160次/分；<110或>160提示胎儿窘迫。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2078","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常足月妊娠的孕周是？","options":["28-36周","37-42周","42周以上","20-28周"],"answer":1,"explanation":"37-42周为足月妊娠；<37周为早产，≥42周为过期妊娠。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2079","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"预产期的计算方法（末次月经第一天）是？","options":["月份减3或加9，日期加7","月份加3，日期加7","月份减3，日期减7","月份加9，日期加14"],"answer":0,"explanation":"预产期（EDC）：末次月经第一天月份减3或加9、日期加7。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2080","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠期母体血容量增加的高峰时间是？","options":["妊娠40周","妊娠12周","妊娠32-34周","妊娠20周"],"answer":2,"explanation":"血容量妊娠6-8周开始增加，32-34周达高峰（增加30-45%），心脏负担最重。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2081","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产前检查开始的时间是？","options":["分娩前","妊娠28周","妊娠32周","确诊早孕时开始"],"answer":3,"explanation":"确诊早孕即开始首次产检，之后按孕周定期检查（孕中期每4周一次等）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2082","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"推算预产期时，末次月经为2026年3月10日，预产期是？","options":["2026年12月17日","2026年12月10日","2026年11月17日","2027年1月10日"],"answer":0,"explanation":"3月10日：月份12（3+9）、日期17（10+7），即2026年12月17日。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2083","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎儿窘迫的主要表现是？","options":["胎心率异常（<110或>160次/分）和胎动减少","孕妇血压升高","孕妇腹痛","阴道流血"],"answer":0,"explanation":"胎儿窘迫：胎心异常、胎动减少、羊水污染（胎粪）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2084","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常分娩（枕先露）胎头衔接的时间是？","options":["初产妇预产期前1-2周","临产后（初产妇）","分娩后","妊娠20周"],"answer":0,"explanation":"初产妇胎头衔接（双顶径入骨盆入口）多在预产期前1-2周；经产妇在临产后。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2085","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"枕先露分娩机制的正确顺序是？","options":["衔接→下降→俯屈→内旋转→仰伸→复位及外旋转→胎肩胎身娩出","下降→衔接→俯屈","内旋转→衔接→下降","俯屈→衔接→仰伸"],"answer":0,"explanation":"分娩机制：衔接、下降、俯屈、内旋转、仰伸、复位及外旋转、胎肩及胎体娩出。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2086","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"临产的重要标志是？","options":["胎头下降","见红","破水","规律宫缩（持续30秒以上、间歇5-6分钟）伴宫颈管消失和宫口扩张"],"answer":3,"explanation":"临产标志：规律且逐渐增强的宫缩（30秒/5-6分钟）+宫颈管进行性消失+宫口扩张+胎先露下降。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2087","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"见红一般出现在分娩前？","options":["2周","1小时","1周","24-48小时"],"answer":3,"explanation":"见红（宫颈黏液栓排出混少量血）多在分娩发动前24-48小时出现，是分娩先兆。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2088","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第一产程（宫颈扩张期）初产妇平均需要？","options":["11-12小时","2小时","6-8小时（经产妇）","24小时"],"answer":0,"explanation":"第一产程初产妇11-12小时，经产妇6-8小时；第二产程初产妇不超过2小时。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2089","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第二产程（胎儿娩出期）初产妇不应超过？","options":["6小时","30分钟","4小时","2小时"],"answer":3,"explanation":"第二产程初产妇≤2小时（硬膜外麻醉≤3小时），经产妇≤1小时。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2090","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第三产程（胎盘娩出期）一般需要？","options":["3分钟","2小时","1小时","5-15分钟，不超过30分钟"],"answer":3,"explanation":"第三产程5-15分钟，超过30分钟为胎盘滞留，需人工剥离。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2091","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎盘剥离的征象不包括？","options":["脐带自行下降延长","宫体变硬呈球形","宫体变软呈囊性感","阴道少量流血"],"answer":2,"explanation":"胎盘剥离征象：宫体变硬呈球形、脐带外延、阴道少量流血、按压耻骨联合上缘脐带不再回缩。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2092","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后出血的定义是？","options":["产后出血任何时候>1000ml","产后1周出血500ml","产后2小时出血300ml","胎儿娩出后24小时内出血量≥500ml（剖宫产≥1000ml）"],"answer":3,"explanation":"产后出血：胎儿娩出后24小时内阴道分娩出血≥500ml或剖宫产≥1000ml，是我国孕产妇死亡首要原因。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2093","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后出血最常见的原因是？","options":["凝血功能障碍","胎盘因素","软产道裂伤","子宫收缩乏力"],"answer":3,"explanation":"产后出血四大原因：宫缩乏力（最常见）、胎盘因素、软产道裂伤、凝血功能障碍。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2094","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后出血宫缩乏力的处理是？","options":["输血（唯一）","立即切除子宫","立即缝合","按摩子宫+宫缩剂（缩宫素）"],"answer":3,"explanation":"宫缩乏力性出血：按摩子宫、应用宫缩剂（缩宫素、麦角新碱等）、宫腔填塞，无效手术。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2095","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"羊水栓塞的典型表现是？","options":["单纯阴道流血","单纯腹痛","单纯发热","分娩前后突发呼吸困难、发绀、休克、DIC"],"answer":3,"explanation":"羊水栓塞：分娩前后突发呛咳、呼吸困难、发绀、休克、DIC，死亡率极高。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2096","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"羊水栓塞的急救措施不包括？","options":["立即剖宫产（所有患者）","抗过敏（糖皮质激素）","纠正缺氧","抗休克、防治DIC"],"answer":0,"explanation":"羊水栓塞急救：正压给氧、抗过敏、抗休克、防治DIC、必要时产科处理；不是所有患者立即剖宫产。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2097","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"异位妊娠（宫外孕）最常见的部位是？","options":["输卵管（壶腹部）","卵巢","腹腔","宫颈"],"answer":0,"explanation":"异位妊娠以输卵管妊娠最常见（95%左右），其中壶腹部最多。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2098","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输卵管妊娠破裂的主要表现是？","options":["白带增多","单纯恶心","发热","突发下腹撕裂样疼痛+腹腔内出血（休克）"],"answer":3,"explanation":"输卵管妊娠破裂：突发一侧下腹撕裂样疼痛、腹腔内出血（晕厥、休克）、阴道少量流血。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2099","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"异位妊娠保守治疗的条件不包括？","options":["破裂型（腹腔内出血）","未破裂、包块小（<4cm）","血HCG<2000U/L","无腹腔内出血"],"answer":0,"explanation":"破裂型异位妊娠需手术治疗；保守治疗（甲氨蝶呤）适用于未破裂、包块小、HCG低者。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2100","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"流产的分类不包括？","options":["习惯性流产（现称复发性流产，属特殊类型）","先兆流产","难免流产","不全流产"],"answer":0,"explanation":"流产类型：先兆、难免、不全、完全流产；复发性流产为特殊类型（连续3次及以上）。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2101","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"先兆流产的表现是？","options":["胚胎组织排出","大量流血+宫口开大","少量阴道流血+轻微腹痛+宫口未开","发热"],"answer":2,"explanation":"先兆流产：少量流血、轻微下腹痛、宫口未开、妊娠组织未排出，可继续妊娠。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2102","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"难免流产的表现是？","options":["无腹痛","宫口未开","少量流血","宫口开大、胚胎组织堵于宫口"],"answer":3,"explanation":"难免流产：宫口已开、妊娠组织堵塞宫口或羊膜囊膨出，流产不可避免。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2103","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠高血压疾病的基本病理生理变化是？","options":["血管扩张","全身小血管痉挛","血液稀释","血容量减少"],"answer":1,"explanation":"妊高症基本病变为全身小动脉痉挛，致各器官缺血（脑、肾、肝、胎盘）。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2104","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子痫前期（重度）的诊断标准不包括？","options":["血压≥160/110mmHg","血压160/110mmHg以下","蛋白尿≥2.0g/24h（或++）","伴头痛、视觉障碍等"],"answer":1,"explanation":"重度子痫前期：血压≥160/110mmHg、蛋白尿明显、伴头痛、视觉障碍、上腹痛等。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2105","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子痫发作时的首要处理是？","options":["立即手术","立即终止妊娠（所有患者）","控制抽搐（硫酸镁静注）","口服降压药"],"answer":2,"explanation":"子痫发作：硫酸镁控制抽搐（首选）、镇静、降压、适时终止妊娠。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2106","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"硫酸镁中毒的表现是？","options":["血压升高","膝反射消失、呼吸抑制、心跳停止","抽搐加重","瞳孔散大（早期）"],"answer":1,"explanation":"硫酸镁中毒：膝反射先消失、呼吸抑制、心跳停止，用药前监测膝反射、呼吸、尿量。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2107","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前置胎盘的典型表现是？","options":["腹痛伴流血","妊娠晚期无痛性反复阴道流血","持续性腹痛","胎心异常（早期）"],"answer":1,"explanation":"前置胎盘：妊娠28周后无痛性反复阴道流血（完全性者出血早且多）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2108","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前置胎盘的确诊方法是？","options":["阴道指检（禁止）","超声检查","CT","腹腔镜"],"answer":1,"explanation":"超声是前置胎盘首选确诊方法；禁止肛门检查和阴道指检（防大出血）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2109","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前置胎盘的处理原则是？","options":["抑制宫缩、止血、纠正贫血、适时终止妊娠","立即剖宫产（所有患者）","阴道分娩（所有患者）","人工破膜"],"answer":0,"explanation":"前置胎盘：期待疗法（抑制宫缩、促胎肺成熟）至36周以上，完全性前置胎盘剖宫产。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2110","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎盘早剥的主要表现是？","options":["持续性腹痛+阴道流血+子宫板状硬","无痛性流血","单纯腰痛","胎心正常（必然）"],"answer":0,"explanation":"胎盘早剥：持续性腹痛、子宫张力高（板状硬）、阴道流血（可无外出血）、胎儿窘迫。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2111","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎盘早剥最严重的并发症是？","options":["产后出血（一般）","DIC和急性肾衰竭","感染","贫血"],"answer":1,"explanation":"胎盘早剥可致DIC、急性肾衰竭、子宫胎盘卒中，危及母儿生命。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2112","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠期糖尿病的筛查时间是？","options":["妊娠12周","妊娠24-28周","妊娠36周","产后"],"answer":1,"explanation":"妊娠24-28周行75g OGTT筛查妊娠期糖尿病（GDM）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2113","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠期糖尿病对胎儿的影响不包括？","options":["胎儿畸形","巨大儿","巨大儿（相反说法）","新生儿低血糖"],"answer":2,"explanation":"GDM可致巨大儿、畸形、新生儿低血糖、呼吸窘迫等；巨大儿是其影响而非相反。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2114","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎膜早破的表现是？","options":["阴道流血","阴道流液（阵发性或持续性）","腹痛","发热"],"answer":1,"explanation":"胎膜早破：临产前胎膜破裂、阴道流液（咳嗽、按压宫底时加重），需预防感染。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2115","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎膜早破的处理不包括？","options":["抬高臀部、防止脐带脱垂","立即阴道检查（所有患者）","预防感染","监测胎心"],"answer":1,"explanation":"胎膜早破禁止不必要的阴道检查（防感染），抬高臀部防脐带脱垂，破膜>12小时预防感染。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2116","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脐带脱垂的紧急处理是？","options":["观察","上推胎头、缓解脐带受压、尽快结束分娩","吸氧（唯一）","等待自然分娩"],"answer":1,"explanation":"脐带脱垂：立即抬高臀部、上推先露部缓解压迫、吸氧，尽快剖宫产结束分娩。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2117","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产褥感染最常见的病原体是？","options":["真菌","单纯病毒","厌氧菌和需氧菌混合感染","结核杆菌"],"answer":2,"explanation":"产褥感染多为厌氧菌与需氧菌混合感染（内源性）。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2118","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产褥期子宫复旧的表现是？","options":["产后10天子宫降至盆腔（耻骨联合上摸不到）","产后1周降至盆腔","产后1个月仍在腹部","不缩小"],"answer":0,"explanation":"子宫复旧：产后1周缩至孕12周大小，10天降至盆腔内（腹部摸不到）。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2119","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后恶露的持续时间（血性恶露）是？","options":["1个月","1天","2周","3-4天"],"answer":3,"explanation":"血性恶露3-4天→浆液性恶露约10天→白色恶露约3周，共4-6周。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2120","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"母乳喂养的优点不包括？","options":["提供免疫物质（SIgA）","增加母亲乳腺癌风险","促进子宫收缩","增进母婴感情"],"answer":1,"explanation":"母乳喂养降低母亲乳腺癌、卵巢癌风险，不增加。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2121","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"初乳的特点是？","options":["产后7天内的乳汁，含免疫球蛋白多","产后1个月的乳汁","脂肪多","蛋白质少"],"answer":0,"explanation":"初乳（产后7天内）质稠、含SIgA等免疫物质多，对新生儿免疫保护重要。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2122","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿脐带护理的原则是？","options":["涂龙胆紫（常规）","湿润包扎","保持干燥、防止污染","频繁牵拉"],"answer":2,"explanation":"脐带残端保持清洁干燥，自然脱落（1-2周），有脓性分泌物及时就医。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2123","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"宫颈癌筛查的首选方法是？","options":["宫颈活检（首选筛查）","宫颈细胞学检查（TCT）+HPV检测","阴道镜（首选筛查）","血CA125"],"answer":1,"explanation":"宫颈癌筛查：TCT+HPV联合筛查；异常者行阴道镜+活检（确诊）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2124","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"宫颈癌的确诊方法是？","options":["HPV检测","TCT","宫颈和宫颈管活组织检查","超声"],"answer":2,"explanation":"宫颈活检（病理）是宫颈癌确诊的金标准。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2125","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"宫颈癌的高危因素不包括？","options":["高危型HPV持续感染","接种HPV疫苗","多个性伴侣","吸烟"],"answer":1,"explanation":"接种HPV疫苗是保护因素；高危型HPV（16、18型）持续感染是主要病因。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2126","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫肌瘤最常见的症状是？","options":["月经改变（经量增多、经期延长）","无痛性肿块（唯一）","白带增多","不孕"],"answer":0,"explanation":"子宫肌瘤最常见症状为月经改变（黏膜下肌瘤最明显），可致贫血。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2127","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫肌瘤的治疗原则是？","options":["全部观察","全部手术","全部药物治疗","无症状者观察，症状明显者手术或药物治疗"],"answer":3,"explanation":"子宫肌瘤无症状者定期观察；症状明显、肌瘤大或生长快者手术（肌瘤剔除或子宫切除）。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2128","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"卵巢肿瘤最常见的并发症是？","options":["破裂","蒂扭转","感染","恶变"],"answer":1,"explanation":"卵巢肿瘤蒂扭转最常见（突然一侧下腹剧痛、恶心呕吐），需急诊手术。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2129","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"卵巢肿瘤蒂扭转的典型表现是？","options":["阴道流血","无痛性包块","突发一侧下腹剧痛伴恶心呕吐、触及包块","发热"],"answer":2,"explanation":"蒂扭转：突发一侧下腹剧痛、持续性绞痛、恶心呕吐、包块压痛，需急诊手术。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2130","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫内膜癌的主要表现是？","options":["闭经","接触性出血（宫颈癌）","痛经","绝经后阴道流血"],"answer":3,"explanation":"子宫内膜癌典型表现：绝经后阴道流血（或围绝经期月经紊乱）。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2131","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫内膜癌的高危因素不包括？","options":["早婚早育","肥胖、高血压、糖尿病","不孕不育","长期雌激素刺激"],"answer":0,"explanation":"子宫内膜癌高危：肥胖、高血压、糖尿病（三联征）、不孕、晚绝经、长期雌激素刺激；早婚早育是宫颈癌高危。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2132","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"葡萄胎的主要表现是？","options":["腹痛（唯一）","子宫小于孕周","无阴道流血","停经后阴道流血+子宫异常增大（大于孕周）"],"answer":3,"explanation":"葡萄胎：停经后不规则阴道流血、子宫异常增大（大于孕周）、HCG异常升高。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2133","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"葡萄胎清宫术后随访的重点是？","options":["血HCG定期监测（至少1年）","血常规","超声（唯一）","胸片（唯一）"],"answer":0,"explanation":"葡萄胎术后随访血HCG至正常后至少1年（每周→每2周→每月），避孕1年。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2134","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"侵蚀性葡萄胎与绒毛膜癌的主要区别是？","options":["有无绒毛结构","HCG高低","发病年龄","转移部位"],"answer":0,"explanation":"侵蚀性葡萄胎可见绒毛结构；绒癌无绒毛、滋养细胞增生，恶性度高。","exam":"医疗编","__sub":"妇产科临床","diff":3,"id":"yl-2135","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"计划生育中，宫内节育器（IUD）的避孕原理是？","options":["干扰受精卵着床","抑制排卵","杀灭精子（唯一）","阻断输卵管"],"answer":0,"explanation":"IUD通过局部炎症反应干扰受精卵着床，属宫内避孕。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2136","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"口服避孕药（短效）的主要避孕原理是？","options":["杀灭受精卵","杀灭精子","阻止着床（唯一）","抑制排卵"],"answer":3,"explanation":"复方短效口服避孕药通过抑制排卵、改变宫颈黏液、干扰内膜等综合作用。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2137","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"紧急避孕药的最佳服用时间是？","options":["1周内","无保护性生活后72小时内（越早越好）","1个月内","随时"],"answer":1,"explanation":"紧急避孕药（左炔诺孕酮）应在无保护性生活后72小时内服用，越早效果越好。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2138","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"人工流产术最常见的并发症是？","options":["子宫穿孔（最严重之一）","人工流产综合征（术中疼痛、心动过缓、血压下降）","感染","宫腔粘连"],"answer":1,"explanation":"人工流产综合征（迷走神经反射）最常见；子宫穿孔、漏吸、宫腔粘连等为其他并发症。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2139","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"药物流产（米非司酮+米索前列醇）适用于？","options":["妊娠49天以内","妊娠3个月","妊娠6个月","任何孕周"],"answer":0,"explanation":"药物流产适用于妊娠≤49天（7周内）的健康妇女。","exam":"医疗编","__sub":"妇产科临床","diff":1,"id":"yl-2140","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输卵管结扎术的时间是？","options":["月经期","月经干净后3-7天（或产后、流产后）","排卵期","妊娠期"],"answer":1,"explanation":"输卵管结扎在月经干净后3-7天（禁性生活）、产后48小时内或流产后进行。","exam":"医疗编","__sub":"妇产科临床","diff":2,"id":"yl-2141","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿是指？","options":["出生后1周内","出生后脐带结扎至28天的婴儿","出生后1个月内（满月）","出生后3天"],"answer":1,"explanation":"新生儿期：脐带结扎至出生后28天（不满4周）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2142","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常新生儿的体重是？","options":["2500-4000g","1500-2000g","4500-5000g","1000-1500g"],"answer":0,"explanation":"正常新生儿出生体重2500-4000g；<2500g为低出生体重儿，>4000g为巨大儿。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2143","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常新生儿出生后身长平均为？","options":["40cm","50cm","60cm","45cm"],"answer":1,"explanation":"新生儿平均身长50cm，1岁时约75cm，2岁时约85-87cm。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2144","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"1岁时小儿体重约为出生时的？","options":["3倍","2倍","4倍","5倍"],"answer":0,"explanation":"出生体重3kg，1岁约10kg（3倍），2岁约12kg。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2145","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2岁至青春期前小儿体重估算公式是？","options":["年龄×2+8（kg）","年龄×3+5","年龄+5","年龄×5"],"answer":0,"explanation":"2-12岁体重=年龄×2+8（kg）；身高=年龄×7+77（cm）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2146","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2-12岁小儿身高的估算公式是？","options":["年龄×7+77（cm）","年龄×5+50","年龄×2+50","年龄×10"],"answer":0,"explanation":"2-12岁身高=年龄×7+77（cm），每年增长约6-7cm。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2147","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿前囟闭合的时间是？","options":["1-1.5岁","出生时","6个月","3岁"],"answer":0,"explanation":"前囟出生时1.5-2cm，1-1.5岁闭合；后囟出生时很小，6-8周内闭合。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2148","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿乳牙萌出的时间是？","options":["2岁","出生时","4-10个月开始","3岁"],"answer":2,"explanation":"乳牙4-10个月萌出（多数6-8个月），2-2.5岁出齐（20颗）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2149","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2岁小儿的乳牙数目是？","options":["约24颗","约16颗","约20颗","约28颗"],"answer":2,"explanation":"乳牙共20颗，2-2.5岁出齐。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2150","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿生长发育的一般规律不包括？","options":["由上到下","由远到近（相反）","由近到远","由粗到细"],"answer":1,"explanation":"生长发育规律：由上到下、由近到远、由粗到细、由简单到复杂、由低级到高级。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2151","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿运动发育的规律是？","options":["二抬四翻六坐八爬十站周岁走","一月坐二月翻","三月走六月站","周岁爬"],"answer":0,"explanation":"运动发育口诀：二抬（抬头）四翻（翻身）六坐八爬十站周岁走。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2152","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病的好发年龄是？","options":["3个月-2岁婴幼儿","新生儿期","学龄期","青春期"],"answer":0,"explanation":"佝偻病好发于3个月-2岁婴幼儿（生长快、户外活动少）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2153","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病激期的骨骼改变不包括？","options":["方颅（早期表现）","方颅","肋骨串珠","手镯脚镯征"],"answer":0,"explanation":"方颅多见于8-9个月以上（激期）；早期（3-6个月）以颅骨软化为主。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2154","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病早期的表现是？","options":["O型腿","方颅","肋骨串珠","易激惹、多汗、枕秃（神经兴奋性增高）"],"answer":3,"explanation":"佝偻病早期（3个月内）：易激惹、烦躁、多汗、枕秃（非特异性）；骨骼改变在激期。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2155","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病的预防措施是？","options":["生后数天开始补充维生素D（400IU/日）并多晒太阳","仅补钙","仅晒太阳","不干预"],"answer":0,"explanation":"预防：新生儿生后数天开始每日补充维生素D 400IU，适当户外活动（晒太阳）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2156","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性手足搐搦症的主要表现是？","options":["高热","惊厥、手足搐搦、喉痉挛（血钙降低）","呕吐","腹泻"],"answer":1,"explanation":"维生素D缺乏性手足搐搦症：血钙降低致惊厥（最常见）、手足搐搦、喉痉挛。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2157","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"营养不良（蛋白质-能量营养不良）最早的表现是？","options":["贫血","水肿","皮下脂肪消失","体重不增或下降"],"answer":3,"explanation":"营养不良最早表现为体重不增或减轻，随后皮下脂肪减少（先腹部）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2158","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"营养不良患儿皮下脂肪减少的顺序是？","options":["四肢→腹部","面部→腹部","腹部→躯干→臀部→四肢→面部","臀部→面部"],"answer":2,"explanation":"皮下脂肪减少顺序：腹部→躯干→臀部→四肢→面部（最后）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2159","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"营养不良患儿最常见的并发症是？","options":["感染（肺炎、腹泻）","营养性贫血","低血糖","水肿"],"answer":1,"explanation":"营养不良易并发营养性贫血、感染、低血糖、维生素缺乏等；贫血最常见。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2160","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻病最常见的病因是？","options":["寄生虫","细菌感染","真菌","轮状病毒感染（秋冬季）"],"answer":3,"explanation":"婴幼儿腹泻以轮状病毒最常见（秋冬季腹泻，蛋花汤样便）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2161","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"轮状病毒肠炎的大便特点是？","options":["黏液便（细菌性）","脓血便","蛋花汤样便、无腥臭味","果酱样便"],"answer":2,"explanation":"轮状病毒肠炎：蛋花汤样或水样便、无腥臭、量多，伴呕吐、发热。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2162","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻重度脱水的主要表现是？","options":["大便次数增多（唯一）","单纯口渴","眼窝明显凹陷、尿量明显减少、皮肤弹性差、精神萎靡","低热"],"answer":2,"explanation":"重度脱水：失水>10%体重，眼窝前囟明显凹陷、皮肤弹性极差、尿量极少、精神萎靡或昏迷。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2163","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻补液的原则是？","options":["先快后慢、先浓后淡、见尿补钾","先慢后快","先补钾后补液","大量补液（无原则）"],"answer":0,"explanation":"补液原则：先快后慢、先浓后淡（先盐后糖）、见尿补钾、抽搐补钙。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2164","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻补钾的浓度是？","options":["0.15-0.3%（不超过0.3%）","0.5%","1%","3%"],"answer":0,"explanation":"小儿补钾浓度0.15-0.3%（40mmol/L以下），速度慢，见尿补钾。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2165","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎最常见的病原体是？","options":["衣原体","支原体","真菌","细菌和病毒（肺炎链球菌常见）"],"answer":3,"explanation":"小儿肺炎以细菌（肺炎链球菌最常见）和病毒为主；支原体肺炎多见于学龄期。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2166","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎的主要表现是？","options":["发热、咳嗽、气促、肺部固定湿啰音","单纯发热","单纯咳嗽无体征","喘息（唯一）"],"answer":0,"explanation":"小儿肺炎：发热、咳嗽、气促、呼吸困难，肺部固定性中细湿啰音。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2167","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎合并心力衰竭的表现不包括？","options":["心率>180次/分","心率减慢","呼吸>60次/分","肝脏短时间内增大"],"answer":1,"explanation":"肺炎合并心衰：心率>180次/分、呼吸>60次/分、肝脏增大、烦躁、发绀加重；心率不减慢。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2168","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎抗生素治疗的原则是？","options":["长期维持","症状消失即停药","单药小剂量","早期、联合、足量、足疗程"],"answer":3,"explanation":"小儿肺炎抗生素：早期、联合、足量、足疗程（体温正常后5-7天，症状体征消失后3天停药）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2169","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"先天性心脏病中最常见的是？","options":["房间隔缺损","室间隔缺损","动脉导管未闭","法洛四联症"],"answer":1,"explanation":"先天性心脏病以室间隔缺损最常见（约30%）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2170","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"法洛四联症的四种畸形不包括？","options":["肺动脉狭窄","房间隔缺损","室间隔缺损","主动脉骑跨"],"answer":1,"explanation":"法洛四联症：肺动脉狭窄、室间隔缺损、主动脉骑跨、右心室肥厚。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2171","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"法洛四联症的主要表现是？","options":["呼吸困难（唯一）","无青紫","水肿","青紫、蹲踞、杵状指"],"answer":3,"explanation":"法洛四联症：青紫（最早出现）、蹲踞、杵状指、缺氧发作。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2172","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"动脉导管未闭的特征性体征是？","options":["舒张期杂音（唯一）","收缩期杂音（唯一）","胸骨左缘第2肋间连续性机器样杂音","心尖区杂音"],"answer":2,"explanation":"动脉导管未闭：胸骨左缘第2肋间连续性机器样杂音，伴周围血管征（水冲脉等）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2173","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"房间隔缺损的典型杂音是？","options":["胸骨左缘第2-3肋间收缩期喷射性杂音（肺动脉瓣区）","连续性杂音","舒张期杂音","心尖区收缩期杂音"],"answer":0,"explanation":"房间隔缺损：肺动脉瓣区（胸骨左缘2-3肋间）收缩期喷射性杂音，第二心音固定分裂。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2174","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"室间隔缺损的典型杂音是？","options":["无杂音","连续性杂音","舒张期杂音","胸骨左缘第3-4肋间粗糙收缩期杂音"],"answer":3,"explanation":"室间隔缺损：胸骨左缘3-4肋间粗糙的全收缩期杂音，伴震颤。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2175","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肾小球肾炎的主要表现是？","options":["大量蛋白尿（肾病综合征）","血尿、水肿、高血压","尿频尿急","肾绞痛"],"answer":1,"explanation":"急性肾炎综合征：血尿（几乎均有）、水肿（晨起眼睑）、高血压，病前1-3周有链球菌感染史。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2176","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肾小球肾炎患儿饮食的原则是？","options":["高盐","低盐（水肿高血压明显时）、限制水（严重时）","高蛋白","高脂"],"answer":1,"explanation":"急性肾炎：水肿高血压时低盐饮食（<1g/日），氮质血症时限制蛋白，严重少尿限水。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2177","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾病综合征患儿大量蛋白尿的标准是？","options":["尿蛋白+","尿蛋白>50mg/（kg·d）或定性+++以上","尿蛋白++","尿蛋白阴性"],"answer":1,"explanation":"小儿肾病综合征：尿蛋白>50mg/（kg·d）或定性+++以上，血浆白蛋白<25g/L。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2178","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肾病综合征首选的治疗药物是？","options":["利尿剂（唯一）","免疫抑制剂","抗生素","糖皮质激素（泼尼松）"],"answer":3,"explanation":"小儿肾病综合征（多数为微小病变型）首选糖皮质激素，疗效好。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2179","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿生理性黄疸出现的时间是？","options":["生后1个月","生后24小时内","生后1周后","生后2-3天，4-6天达高峰"],"answer":3,"explanation":"生理性黄疸：生后2-3天出现、4-6天高峰、足月儿2周内消退；生后24小时内出现为病理性。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2180","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿病理性黄疸的特点不包括？","options":["生后24小时内出现","黄疸消退后再次出现（属病理性）","足月儿>2周未退","血清胆红素超过正常上限"],"answer":1,"explanation":"病理性黄疸：早（24小时内）、快（胆红素上升快）、高（超过正常值）、久（>2周）、退而复现。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2181","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿胆红素脑病（核黄疸）的好发部位是？","options":["大脑皮层（唯一）","基底核（脑基底节）","小脑","脊髓"],"answer":1,"explanation":"胆红素脑病：未结合胆红素沉积于基底核等，表现为嗜睡、拒奶、尖叫、抽搐。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2182","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿Apgar评分的五项指标是？","options":["体温、脉搏、呼吸、血压、神志","心率、呼吸、肌张力、喉反射、皮肤颜色","哭声、吸吮、拥抱、觅食、握持","体重、身长、头围、囟门、体温"],"answer":1,"explanation":"Apgar评分：心率、呼吸、肌张力、喉反射（弹足底反应）、皮肤颜色，每项0-2分。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2183","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿Apgar评分8-10分表示？","options":["重度窒息","轻度窒息","正常（无窒息）","濒死"],"answer":2,"explanation":"Apgar评分8-10分正常；4-7分轻度（青紫）窒息；0-3分重度（苍白）窒息。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2184","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿窒息复苏的首要步骤是？","options":["胸外按压","清理呼吸道（保持气道通畅）","药物治疗","保暖（唯一）"],"answer":1,"explanation":"新生儿复苏ABCDE：清理呼吸道（A）→建立呼吸（B）→恢复循环（C）→药物（D）→评估（E）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2185","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿窒息复苏胸外按压的指征是？","options":["无指征","出生后立即","心率>100次/分","正压通气30秒后心率<60次/分"],"answer":3,"explanation":"正压通气30秒后心率仍<60次/分，行胸外按压（与正压通气3:1）。","exam":"医疗编","__sub":"儿科临床","diff":3,"id":"yl-2186","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿败血症最常见的感染途径是？","options":["血行（母体）","呼吸道","消化道","脐部和皮肤黏膜"],"answer":3,"explanation":"新生儿败血症以脐部、皮肤黏膜感染最常见（脐炎、脓疱疮等）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2187","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿破伤风的感染原因是？","options":["消化道","呼吸道","脐带断端处理不当（接生消毒不严）","母乳"],"answer":2,"explanation":"新生儿破伤风（四六风）：接生时脐带断端消毒不严，破伤风梭菌侵入，生后4-7天发病。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2188","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿颅内出血最常见的原因是？","options":["产伤和缺氧","感染","凝血障碍","维生素K缺乏（迟发型）"],"answer":0,"explanation":"新生儿颅内出血以产伤（足月儿）和缺氧（早产儿）为主要原因。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2189","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿硬肿症（寒冷损伤综合征）的主要表现是？","options":["高热","低体温、皮肤硬肿","黄疸","腹泻"],"answer":1,"explanation":"新生儿寒冷损伤综合征：低体温（<35℃）、皮肤硬肿（先下肢后全身）、多器官损害。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2190","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿硬肿症复温的原则是？","options":["逐渐复温（体温每小时升高0.5-1℃）","快速复温（立即）","缓慢复温（每天1℃）","不复温"],"answer":0,"explanation":"新生儿硬肿症复温：逐渐复温，轻中度6-12小时内恢复体温，重度12-24小时。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2191","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿呼吸心跳骤停的复苏按压深度（儿童）是？","options":["约为胸廓前后径的1/3（约5cm）","2cm","8cm","10cm"],"answer":0,"explanation":"儿童CPR按压深度约5cm（胸廓前后径1/3），婴儿约4cm。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2192","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿用药剂量的计算最常用方法是？","options":["按体重计算（kg）","按身高","按年龄直接套用","按体表面积（唯一）"],"answer":0,"explanation":"小儿剂量最常按体重计算；某些药物（化疗药）按体表面积更精确。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2193","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿液体疗法中，等渗性脱水首选补充？","options":["高张液","等张液","2/3张液","1/2张含钠液（如3:2:1液）"],"answer":3,"explanation":"等渗性脱水用1/2张含钠液；低渗性用2/3张；高渗性用1/3张。","exam":"医疗编","__sub":"儿科临床","diff":3,"id":"yl-2194","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻低钾血症补钾的时间要求是？","options":["不补钾","立即补钾","补液后24小时","见尿后补钾"],"answer":3,"explanation":"见尿（尿量>30ml/h）后补钾，防止高钾血症。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2195","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿高热惊厥的特点是？","options":["任何年龄","6个月-5岁、体温>38.5℃、发作后神志清楚","体温正常时发作","发作后持续昏迷"],"answer":1,"explanation":"高热惊厥：6个月-5岁、发热早期（>38.5℃）发作、持续<10分钟、发作后神志清、无神经系统异常。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2196","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿高热惊厥发作时的紧急处理是？","options":["立即口服退热药","保持呼吸道通畅、防止舌咬伤、降温","立即静脉输液","按压肢体"],"answer":1,"explanation":"惊厥处理：平卧头偏一侧、清理呼吸道、防止舌咬伤（牙垫）、吸氧、退热，必要时止惊药。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2197","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿结核菌素试验（PPD）阳性的判断标准是？","options":["硬结<5mm","硬结直径≥5mm（20mm以上或有水疱为强阳性）","无硬结","仅红斑"],"answer":1,"explanation":"PPD：硬结5-9mm弱阳性（+）、10-19mm阳性（++）、≥20mm或水疱坏死为强阳性（+++）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2198","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿接种卡介苗的部位是？","options":["左上臂三角肌下端皮内","右上臂皮下","大腿肌肉","臀部皮下"],"answer":0,"explanation":"卡介苗接种于左上臂三角肌下端皮内（0.1ml），8-12周后做PPD试验验证。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2199","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，乙肝疫苗的接种时间是？","options":["8个月","出生、3个月、6个月","2、3、4个月","0、1、6个月"],"answer":3,"explanation":"乙肝疫苗：0（出生24小时内）、1、6个月各1针。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2200","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，脊髓灰质炎疫苗的接种时间是？","options":["2、3、4个月（口服糖丸）","出生时","6个月","1岁"],"answer":0,"explanation":"脊灰疫苗：2、3、4个月各口服1次（糖丸），4岁加强。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2201","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，百白破疫苗的接种时间是？","options":["2个月","出生时","3、4、5个月","1岁"],"answer":2,"explanation":"百白破三联疫苗：3、4、5个月各1针，18-24个月加强。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2202","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，麻疹疫苗的接种时间是？","options":["8个月","出生时","6个月","2岁"],"answer":0,"explanation":"麻疹减毒活疫苗：8个月初种，18-24个月复种。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2203","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，卡介苗的接种时间是？","options":["6个月","2个月","出生时","1岁"],"answer":2,"explanation":"卡介苗在出生时（24小时内）接种。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2204","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，乙脑疫苗的接种时间是？","options":["3个月","出生时","8个月（灭活疫苗初种2针）","6个月"],"answer":2,"explanation":"乙脑灭活疫苗：8个月初种2针（间隔7-10天），2岁、6岁加强。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2205","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻病的治疗原则不包括？","options":["液体疗法","调整饮食","立即使用止泻药（强力止泻）","合理用药"],"answer":2,"explanation":"小儿腹泻治疗：调整饮食、液体疗法（核心）、合理用药、微生态制剂；不宜强力止泻（毒素滞留）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2206","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎的护理措施不包括？","options":["大量喂食（避免呛咳）","保持呼吸道通畅","定时翻身拍背","室内空气流通"],"answer":0,"explanation":"肺炎患儿应少量多次喂食，避免呛咳加重；保持气道通畅、拍背排痰。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2207","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿贫血的常见类型是？","options":["再生障碍性贫血","营养性缺铁性贫血","溶血性贫血","地中海贫血（地区性）"],"answer":1,"explanation":"小儿贫血以营养性缺铁性贫血最常见（6个月-2岁高发）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2208","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿缺铁性贫血的主要原因是？","options":["慢性失血","铁摄入不足（辅食添加不及时）","吸收障碍（成人）","溶血"],"answer":1,"explanation":"婴幼儿缺铁性贫血主要因铁摄入不足（未及时添加含铁辅食）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2209","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿缺铁性贫血的预防措施是？","options":["及时添加含铁辅食（4-6个月起）","补充维生素C（唯一）","输血","补钙"],"answer":0,"explanation":"预防：母乳喂养、4-6个月及时添加含铁辅食（强化铁米粉、蛋黄、肝泥等）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2210","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿维生素D缺乏的预防措施是？","options":["不干预","出生时大量补充","仅靠食物","生后数天开始补充维生素D 400IU/日"],"answer":3,"explanation":"预防佝偻病：生后数天开始每日维生素D 400IU（早产儿加倍），多晒太阳。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2211","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎合并心衰的紧急处理是？","options":["立即手术","强心（地高辛）、利尿、镇静、吸氧","抗生素加量","补液"],"answer":1,"explanation":"肺炎合并心衰：吸氧、镇静、强心（地高辛）、利尿、扩血管。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2212","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻脱水伴循环不良（重度）时，扩容阶段用？","options":["缓慢滴注","2:1等张含钠液20ml/kg，30-60分钟内静脉输入","口服补液","仅用生理盐水"],"answer":1,"explanation":"重度脱水扩容：2:1等张含钠液（或生理盐水）20ml/kg，30-60分钟快速输入。","exam":"医疗编","__sub":"儿科临床","diff":3,"id":"yl-2213","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻口服补液盐（ORS）适用于？","options":["肠梗阻","重度脱水","频繁呕吐者","轻中度脱水无呕吐者"],"answer":3,"explanation":"ORS适用于轻中度脱水、无严重呕吐者；重度脱水或呕吐严重者静脉补液。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2214","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿生理性腹泻的特点是？","options":["大便次数增多但生长发育正常、无需特殊治疗","伴发热","体重下降","需要抗生素"],"answer":0,"explanation":"生理性腹泻：母乳喂养儿大便次数多（6-10次/日）但生长发育正常，添加辅食后好转。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2215","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿脐炎的病原体主要是？","options":["病毒","大肠埃希菌（唯一）","厌氧菌（唯一）","金黄色葡萄球菌"],"answer":3,"explanation":"新生儿脐炎以金黄色葡萄球菌最常见，表现为脐部红肿、脓性分泌物。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2216","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿乳腺肿大和假月经的原因是？","options":["母体雌激素影响（生后中断）","感染","肿瘤","内分泌疾病"],"answer":0,"explanation":"新生儿受母体雌激素影响，可有乳腺肿大（2-3周消退）、阴道少量出血（假月经）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2217","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿生理性体重下降的幅度是？","options":["不下降","下降20%","出生后3-4天下降6-9%，7-10天恢复","下降50%"],"answer":2,"explanation":"新生儿生理性体重下降：3-4天最低（下降6-9%），7-10天恢复出生体重。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2218","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"早产儿是指？","options":["胎龄<40周","胎龄<37周出生的新生儿","胎龄>42周","体重<2500g"],"answer":1,"explanation":"早产儿：胎龄<37周；过期产儿≥42周；低出生体重儿<2500g。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2219","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"早产儿保暖的适宜温度（中性温度）是？","options":["根据体重调节（一般32-35℃暖箱）","固定26℃","固定40℃","室温即可"],"answer":0,"explanation":"早产儿中性温度根据体重和日龄调节（体重越低、日龄越小，所需温度越高）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2220","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿惊厥最常见的病因是？","options":["代谢异常","癫痫","颅内感染","高热惊厥"],"answer":3,"explanation":"小儿惊厥以高热惊厥最常见（6个月-5岁）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2221","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人测量脉搏时，首选的动脉是","options":["肱动脉","桡动脉","颈动脉","股动脉"],"answer":1,"explanation":"桡动脉表浅、易触及且不影响病人休息，是测量脉搏的首选部位。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2222","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常成人安静状态下的呼吸频率为","options":["28～32次/分","10～14次/分","22～26次/分","16～20次/分"],"answer":3,"explanation":"正常成人安静状态下呼吸频率为16～20次/分，节律均匀。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2223","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测量呼吸时护士的手仍置于病人脉搏部位是为了","options":["判断脉搏是否规律","转移病人注意力，避免其刻意控制呼吸","测量脉搏与呼吸的比例","防止病人躁动"],"answer":1,"explanation":"呼吸受意识控制，护士手留于诊脉部位可转移病人注意，获得真实呼吸频率。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2224","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"体温上升期病人的表现为","options":["畏寒、皮肤苍白、无汗","皮肤潮红、灼热","大量出汗","脉搏细速、血压下降"],"answer":0,"explanation":"体温上升期产热增加、散热减少，表现为畏寒、寒战、皮肤苍白、干燥无汗。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2225","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高热病人退热期大量出汗时应特别警惕","options":["心律失常","过敏反应","虚脱（低血容量性休克）","脑水肿"],"answer":2,"explanation":"退热期大量出汗丢失体液，可致血容量不足，应警惕虚脱，及时补充水分和电解质。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2226","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测量口腔温度的适宜时间为","options":["5分钟","1分钟","3分钟","10分钟"],"answer":2,"explanation":"口温测量需3分钟，腋温需10分钟，肛温需3分钟。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2227","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"不宜测口温的病人是","options":["术后恢复期者","发热者","口鼻手术者","高血压病人"],"answer":2,"explanation":"口鼻手术、呼吸困难、昏迷、婴幼儿等不宜测口温，以免咬碎体温计或影响测量。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2228","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"水银体温计不慎被咬碎，应首先","options":["立即口服大量牛奶或蛋清","催吐","洗胃","服用泻药"],"answer":0,"explanation":"误服水银后可口服牛奶、蛋清等保护胃黏膜，并观察，金属汞不易吸收。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2229","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"血压测量的正确方法是","options":["袖带下缘距肘窝5cm以上","袖带下缘距肘窝2～3cm","袖带缠于肘窝处","袖带过紧不影响结果"],"answer":1,"explanation":"袖带下缘距肘窝2～3cm，松紧以能插入一指为宜。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2230","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测血压时袖带过松会导致","options":["测得血压偏高","测得血压偏低","血压不变","测不出血压"],"answer":0,"explanation":"袖带过松需充气更多压力才能阻断血流，测得血压偏高。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2231","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"成人无菌注射前皮肤消毒常用消毒剂","options":["0.5%碘伏","75%乙醇","3%过氧化氢","0.1%苯扎溴铵"],"answer":0,"explanation":"注射部位皮肤消毒常用0.5%碘伏，消毒两遍，待干后注射。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2232","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌持物钳的正确使用方法是","options":["钳端向下，不可倒转向上","钳端向上","浸泡在消毒液中的部分不限","可夹取无菌物品换药后继续使用"],"answer":0,"explanation":"无菌持物钳使用时保持钳端向下，防止消毒液倒流污染钳端。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2233","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌包打开后未用完，有效期为","options":["4小时","24小时","7天","2小时"],"answer":1,"explanation":"无菌包打开后剩余物品有效期为24小时；铺好的无菌盘有效期为4小时。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2234","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌盘铺好后有效期为","options":["7天","24小时","12小时","4小时"],"answer":3,"explanation":"铺好的无菌盘应在4小时内使用，超过时间视为污染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2235","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"已开启的无菌溶液瓶内剩余溶液，有效期不超过","options":["7天","4小时","48小时","24小时"],"answer":3,"explanation":"开启的无菌溶液应在4小时内用完；剩余溶液标注开启时间，超过24小时不得使用。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2236","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"取用无菌溶液时，正确的做法是","options":["先核对瓶签再检查溶液性质","直接倒入无菌容器","手触及瓶口","瓶塞内面朝下放置"],"answer":0,"explanation":"取无菌溶液应先核对瓶签、检查溶液有无浑浊沉淀，瓶塞内面朝上放置，手不可触及瓶口。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2237","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"戴无菌手套时，正确的做法是","options":["脱手套时先撕破","手可低于腰部","手套外面可触及皮肤","戴好手套的手保持在腰以上视线范围内"],"answer":3,"explanation":"戴无菌手套后双手应保持在腰部以上、视线范围内，避免污染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2238","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脱无菌手套的正确方法是","options":["用水冲洗后脱","直接撕下","先洗手后脱","手套外面相互捏脱，勿使手套外面触及皮肤"],"answer":3,"explanation":"脱手套应从手套口翻转脱下，避免手套外面（污染面）触及皮肤。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2239","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"皮下注射常选部位不包括","options":["上臂三角肌下缘","腹部","大腿外侧","足底"],"answer":0,"explanation":"皮下注射常选上臂三角肌下缘、腹部、后背、大腿外侧等，足底无皮下组织不宜注射。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2240","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"臀大肌注射连线定位法正确的是","options":["外下1/3处","内上1/3处","髂前上棘与尾骨连线的外上1/3处","内下1/3处"],"answer":2,"explanation":"臀大肌注射连线法：取髂前上棘与尾骨连线的外上1/3处为注射区。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2241","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2岁以下婴幼儿不宜选用臀大肌注射的原因是","options":["臀大肌未发育完善，有损伤坐骨神经的危险","吸收太慢","疼痛明显","易感染"],"answer":0,"explanation":"婴幼儿臀大肌发育不全且坐骨神经位置表浅，宜选臀中肌、臀小肌或股外侧肌注射。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2242","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"静脉注射进针角度为","options":["45°","5°","15°～30°","90°"],"answer":2,"explanation":"静脉注射进针角度一般为15°～30°，皮内注射为5°，肌内注射为90°。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2243","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"皮内注射前臂试验时，针尖斜面应","options":["深达肌层","垂直刺入","斜面朝下","与皮肤平行刺入"],"answer":3,"explanation":"皮内注射使针尖斜面与皮肤平行刺入皮内，形成皮丘。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2244","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"青霉素皮试液每毫升含青霉素","options":["1000U","100U","200～500U","5000U"],"answer":2,"explanation":"青霉素皮试液浓度为每毫升含青霉素200～500U，皮内注射0.1ml。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2245","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"青霉素过敏性休克首选的抢救药物是","options":["盐酸肾上腺素","地塞米松","异丙嗪","多巴胺"],"answer":0,"explanation":"青霉素过敏性休克应立即皮下注射0.1%盐酸肾上腺素0.5～1ml，为首选抢救药。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2246","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"链霉素过敏反应抢救除肾上腺素外还应使用","options":["碳酸氢钠","葡萄糖酸钙","阿托品","地西泮"],"answer":1,"explanation":"链霉素过敏可静脉注射10%葡萄糖酸钙或5%氯化钙，因钙剂可与链霉素络合减轻毒性反应。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2247","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"破伤风抗毒素（TAT）皮试阳性者应","options":["停止一切注射","采用脱敏注射分四次进行","直接全量注射","改用口服药"],"answer":1,"explanation":"TAT皮试阳性者采用脱敏注射法，分4次剂量递增肌内注射，并备好抢救药品。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2248","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"静脉输液的目的不包括","options":["输入药物","纠正酸碱失衡","补充水分和电解质","增加体重"],"answer":2,"explanation":"静脉输液用于补充体液、电解质、营养及输入药物，不以增加体重为目的。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2249","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肺水肿的典型表现是","options":["干咳无痰","咳铁锈色痰","咳脓痰","咳粉红色泡沫痰"],"answer":3,"explanation":"循环负荷过重（急性肺水肿）表现为呼吸困难、咳粉红色泡沫痰，应立即停止输液、端坐位、高流量吸氧并湿化瓶内加乙醇。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2250","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"静脉输液发生空气栓塞时，应立即协助病人取","options":["平卧位","右侧卧位","左侧卧位并头低足高","半坐卧位"],"answer":2,"explanation":"空气栓塞应立即取左侧卧位、头低足高位，使气泡避开肺动脉口。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2251","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"静脉炎的护理措施正确的是","options":["按摩挤压局部","继续原处输液","患肢下垂","停止在患肢输液，抬高患肢并湿热敷"],"answer":3,"explanation":"静脉炎应停止患处输液、抬高患肢、局部湿热敷或理疗，避免按摩。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2252","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"发热反应多发生在输液过程中","options":["24小时后","12小时后","数分钟至1小时内","3天后"],"answer":2,"explanation":"输液发热反应多发生于输液后数分钟至1小时内，表现为寒战、发热。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2253","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输血前须双人核对的目的是","options":["防止过敏","防止溶血","防止输错血","防止感染"],"answer":2,"explanation":"输血前双人核对病人信息与血袋信息，防止输错血型造成严重溶血反应。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2254","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"大量输血后易出现","options":["低血钾","高血钙","低血钙（枸橼酸钠中毒）","高血钠"],"answer":2,"explanation":"大量输血时枸橼酸钠与血钙结合致低血钙，表现为手足抽搐，应静脉补充钙剂。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2255","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"溶血反应的最早表现是","options":["黄疸","头部胀痛、四肢麻木、腰背酸痛","少尿","发热寒战"],"answer":1,"explanation":"血管内溶血反应初期表现为头部胀痛、四肢麻木、腰背部剧烈疼痛，随后出现黄疸和血红蛋白尿。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2256","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输血引起溶血反应的根本原因是","options":["输血过快","血型不合","血液污染","输血量过多"],"answer":1,"explanation":"溶血反应多因ABO血型不合导致红细胞破坏，是最严重的输血反应。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2257","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"氧疗时湿化瓶内常规加入","options":["生理盐水","灭菌注射用水（湿化液）","75%乙醇","蒸馏水加乙醇"],"answer":1,"explanation":"常规氧疗湿化瓶内加灭菌注射用水或冷开水湿化氧气；急性肺水肿时才加20%～30%乙醇。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2258","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"鼻导管吸氧时氧流量为2L/min，氧浓度约为","options":["29%","20%","40%","50%"],"answer":0,"explanation":"吸氧浓度（%）=21+4×氧流量，2L/min时为21+8=29%。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2259","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性阻塞性肺疾病病人宜采用的氧疗方式","options":["高流量间断吸氧","低流量持续吸氧","纯氧吸入","高流量持续吸氧"],"answer":1,"explanation":"COPD病人呼吸中枢对二氧化碳敏感性降低，应给予低流量（1～2L/min）持续吸氧。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2260","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"用氧安全措施错误的是","options":["氧气筒旁可使用明火","防震、防热","远离火源","氧气筒内不可用尽"],"answer":0,"explanation":"氧气筒应防震、防火、防热、防油，周围严禁烟火，氧气不可用尽以免杂质进入。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2261","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"吸痰时每次吸引时间不超过","options":["3分钟","30秒","1分钟","15秒"],"answer":3,"explanation":"每次吸痰时间不超过15秒，以免造成缺氧。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2262","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"吸痰管插入口腔或鼻腔的深度","options":["插至咽喉部（约10～15cm）后吸引","插入5cm即吸引","插入越深越好","插入后立即吸引"],"answer":0,"explanation":"吸痰管应插至咽喉部再开始吸引，避免损伤黏膜并提高吸痰效果。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2263","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"鼻饲流质饮食每次量不超过","options":["200ml","500ml","100ml","300ml"],"answer":0,"explanation":"鼻饲每次不超过200ml，间隔时间不少于2小时，温度38～40℃。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2264","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"鼻饲液温度适宜的是","options":["45～50℃","20℃","38～41℃","室温"],"answer":2,"explanation":"鼻饲液温度以38～41℃为宜，过冷过热均刺激胃肠道。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2265","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"长期鼻饲者应每日进行","options":["膀胱冲洗","蒸汽吸入","雾化吸入","口腔护理"],"answer":3,"explanation":"长期鼻饲者每日口腔护理2次，防止口腔感染，并定期更换胃管。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2266","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为女病人导尿时，导尿管插入尿道的深度为","options":["10～12cm","7～9cm","2～3cm","4～6cm"],"answer":3,"explanation":"女病人尿道长约3～5cm，导尿时插入4～6cm见尿后再进1cm。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2267","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为男病人导尿时，导尿管插入深度为","options":["4～6cm","10～12cm","20～22cm","15～17cm"],"answer":2,"explanation":"男病人尿道长约18～20cm，导尿时插入20～22cm见尿后再进1～2cm。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2268","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"留置导尿管的病人，为防止感染应","options":["引流管高于膀胱","每周更换尿管即可","每日清洁尿道口，保持引流通畅","尿袋随时可高于膀胱"],"answer":2,"explanation":"留置导尿应每日清洁消毒尿道口，引流管和尿袋低于膀胱，防止逆行感染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2269","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为膀胱高度充盈的病人导尿首次放尿不应超过","options":["1000ml","500ml","200ml","1500ml"],"answer":0,"explanation":"一次放尿不超过1000ml，防止膀胱内压骤降引起虚脱或膀胱出血。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2270","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"大量不保留灌肠时，灌肠液液面距肛门的高度为","options":["40～60cm","20cm","80cm","100cm"],"answer":0,"explanation":"大量不保留灌肠液面距肛门40～60cm，温度39～41℃，插入肛门7～10cm。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2271","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝性脑病病人禁用的灌肠液是","options":["肥皂水","生理盐水","温开水","乳果糖溶液"],"answer":0,"explanation":"肥皂水为碱性，促进氨吸收，加重肝性脑病，应选用生理盐水或弱酸性溶液灌肠。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2272","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"降温灌肠时灌肠液的温度为","options":["20℃以下","39～41℃","37℃","28～32℃"],"answer":3,"explanation":"降温灌肠用28～32℃等渗盐水，中暑病人用4℃等渗盐水。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2273","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"冷疗减轻疼痛的机制是","options":["加速致痛物质排出","促进血液循环","减轻组织充血","降低神经末梢敏感性"],"answer":3,"explanation":"冷疗使神经末梢敏感性降低而减轻疼痛；热疗降低痛觉神经兴奋性并促进炎症消散。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2274","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乙醇擦浴的浓度为","options":["50%","25%～35%","75%","95%"],"answer":1,"explanation":"乙醇擦浴用25%～35%乙醇，温度约30℃，以离心方向进行，禁擦胸前区、腹部、后颈、足底。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2275","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乙醇擦浴禁擦足底的原因是","options":["引起疼痛","引起冻伤","可引起反射性心率减慢和腹泻","影响散热"],"answer":2,"explanation":"足底对冷敏感，冷刺激可引起反射性冠状动脉收缩和腹泻。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2276","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"热水袋使用时水温为","options":["60～70℃","40℃","80℃","90℃"],"answer":0,"explanation":"成人热水袋水温60～70℃，婴幼儿、老年人、末梢循环差者不超过50℃，外加布套。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2277","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"压疮好发部位不包括","options":["腹部脂肪丰厚处","枕部","骨隆突处","足跟"],"answer":2,"explanation":"压疮好发于骨隆突处等长期受压部位，腹部脂肪丰厚处不易发生。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2278","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"压疮淤血红润期的护理重点是","options":["清创换药","去除危险因素，避免压疮继续发展","外科手术","应用抗生素"],"answer":1,"explanation":"淤血红润期应增加翻身次数、避免受压、改善循环，防止发展至更深分期。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2279","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"预防压疮最有效的措施是","options":["按摩骨突处","定时翻身，避免局部长期受压","使用气圈","保持皮肤干燥"],"answer":1,"explanation":"定时翻身、解除局部压力是预防压疮最有效的措施。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2280","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"医院感染是指","options":["出院后立即发生的感染均不算","入院时已存在的感染","入院24小时内的感染","病人在入院48小时后发生的感染"],"answer":3,"explanation":"入院48小时后发生的感染且入院时不存在或处于潜伏期者为医院感染。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2281","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"属于医院感染的是","options":["新生儿经产道获得的感染","入院时已存在的阑尾炎","入院后24小时内的原有感染复发","术后伤口感染"],"answer":3,"explanation":"术后伤口感染属于医院感染；入院时已存在或潜伏期内的感染不属于。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2282","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"紫外线消毒的有效距离和时间是","options":["3米内15分钟","5米内10分钟","1米内5分钟","2米内照射30分钟以上"],"answer":3,"explanation":"紫外线灯管消毒有效距离2米内，照射时间30分钟以上。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2283","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"紫外线灯管使用中应每周用","options":["干布擦拭","清水冲洗","75%乙醇棉球擦拭灯管","消毒液浸泡"],"answer":2,"explanation":"紫外线灯管每周用75%～95%乙醇棉球擦拭一次，保持清洁以维持杀菌效果。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2284","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"耐高温、耐湿物品首选的灭菌方法是","options":["紫外线照射","压力蒸汽灭菌法","环氧乙烷灭菌","过氧乙酸浸泡"],"answer":1,"explanation":"压力蒸汽灭菌法杀菌力强、效果好，是耐高温耐湿物品的首选灭菌方法。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2285","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"化学消毒剂戊二醛浸泡灭菌器械的时间为","options":["10小时以上","30分钟","2小时","1小时"],"answer":0,"explanation":"2%戊二醛浸泡灭菌需10小时以上，消毒需20～45分钟。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2286","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"穿脱隔离衣的正确顺序是","options":["穿：先穿袖后系领；脱：先解领后解袖","穿：先系领后穿袖","脱：先脱袖后解领","随意顺序"],"answer":0,"explanation":"穿隔离衣先穿两袖再系领口；脱时先解领口再解袖口，避免污染。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2287","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"严密隔离适用于","options":["水痘","麻疹","霍乱","流行性感冒"],"answer":2,"explanation":"霍乱等传染性强、死亡率高的疾病需严密隔离；麻疹、水痘为呼吸道隔离。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2288","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心跳呼吸骤停时胸外按压与人工呼吸的比例（单人）为","options":["15:2","30:2","5:1","10:2"],"answer":1,"explanation":"单人及双人CPR按压与吹气比例均为30:2。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2289","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸外心脏按压的部位是","options":["左胸部","心前区","胸骨上段","胸骨中下1/3交界处"],"answer":3,"explanation":"成人胸外按压部位为胸骨中下1/3交界处（两乳头连线中点），深度5～6cm，频率100～120次/分。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2290","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心肺复苏时判断呼吸及脉搏的时间不应超过","options":["5秒","30秒","1分钟","10秒"],"answer":3,"explanation":"判断颈动脉搏动与呼吸应在10秒内完成，以免延误抢救。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2291","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"海姆立克急救法用于","options":["休克","心搏骤停","溺水","气道异物梗阻"],"answer":3,"explanation":"海姆立克手法通过冲击腹部产生气流排出气道异物，用于气道梗阻。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2292","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"单人搬运病人时，正确的方法是","options":["两人抬四肢","拖行","将病人抱起，使其双臂环抱搬运者颈部","用床单拖拽"],"answer":2,"explanation":"单人搬运宜采用抱持法，病人双臂环抱搬运者颈后，稳妥移动。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2293","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"三人平托搬运脊柱损伤病人的正确方法是","options":["一人抱起","保持脊柱轴线位，平托放于硬板担架","两人抬肩抬腿","背负搬运"],"answer":1,"explanation":"脊柱损伤搬运应保持脊柱轴线一致，三人平托置于硬板担架，防止脊髓损伤。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2294","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"轮椅运送病人时，正确的做法是","options":["病人自行上下","闸制动后再让病人上下","下坡时倒行无需注意","快速推行"],"answer":1,"explanation":"轮椅使用应先闸制动，协助病人安全转移；下坡应减速、病人头朝后。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2295","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病人出院时的床单位处理不包括","options":["立即铺备用床","撤去污被服","床垫、枕芯日光暴晒","病室通风"],"answer":0,"explanation":"出院处理先消毒床单位，再铺备用床，不能先铺床后消毒。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2296","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"特级护理适用于","options":["择期手术前病人","病情稳定者","康复期病人","病情危重、随时需要抢救的病人"],"answer":3,"explanation":"特级护理用于病情危重、需随时观察抢救的病人，专人24小时护理。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2297","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"一级护理病人巡视频率为","options":["每2小时一次","每小时一次","每4小时一次","每30分钟一次"],"answer":1,"explanation":"一级护理每小时巡视一次，二级护理每2小时，三级护理每3小时。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2298","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"抢救物品管理的“五定”不包括","options":["定人保管","定点安置","定数量品种","定期使用"],"answer":2,"explanation":"五定为：定数量品种、定点安置、定人保管、定期消毒灭菌、定期检查维修，无“定期使用”。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2299","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"医嘱“st”表示","options":["立即执行，限用一次","每小时一次","必要时","长期有效"],"answer":0,"explanation":"st为立即执行，限用一次；sos为必要时，qod为隔日一次。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2300","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"口头医嘱的处理方法是","options":["直接执行不记录","护士复述确认后执行，抢救后6小时内补记","拒绝执行","让家属签字"],"answer":1,"explanation":"抢救中执行口头医嘱须复述确认，用后保留安瓿，抢救结束后6小时内补记。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2301","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病区交班内容不包括","options":["手术病人","新入病人","危重病人","病人的私人隐私信息"],"answer":3,"explanation":"交班重点为新入、危重、手术、病情变化病人，不涉及无关隐私信息。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2302","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"长期备用医嘱的缩写是","options":["prn","sos","st","qid"],"answer":0,"explanation":"prn为长期备用医嘱，sos为临时备用医嘱（12小时内有效）。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2303","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"给药时间“ac”表示","options":["晨起","饭后","睡前","饭前"],"answer":3,"explanation":"ac为饭前，pc为饭后，hs为睡前，qm为每晨。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2304","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"服用强心苷类药物前应先测量","options":["心率（脉搏）","血压","呼吸","体温"],"answer":0,"explanation":"服用洋地黄类药物前测心率，低于60次/分应暂停给药并报告医生。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2305","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"雾化吸入的目的不包括","options":["湿化气道","稀释痰液","治疗呼吸道感染","降低血糖"],"answer":0,"explanation":"雾化吸入用于湿化气道、稀释痰液、治疗呼吸道疾病，与血糖无关。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2306","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"超声雾化吸入时，水槽内水温不得超过","options":["50℃","30℃","60℃","70℃"],"answer":0,"explanation":"超声雾化水槽水温超过50℃应停机换水，以免损坏机器和影响药效。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2307","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"氧气雾化吸入时，氧流量一般为","options":["2～4L/min","1～2L/min","6～8L/min","10L/min"],"answer":2,"explanation":"氧气雾化吸入氧流量6～8L/min，使药液形成雾状。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2308","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"疼痛病人应用止痛药的原则是","options":["疼痛时才给强效药","一律肌注","按阶梯给药，尽量口服","大剂量长期使用"],"answer":2,"explanation":"癌痛三阶梯止痛原则：口服给药、按阶梯给药、按时给药、个体化、注意细节。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2309","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"临终病人心理反应的五个阶段依次为","options":["否认期、协议期、愤怒期、忧郁期、接受期","愤怒期、否认期、接受期、协议期、忧郁期","接受期、否认期、愤怒期、协议期、忧郁期","否认期、愤怒期、协议期、忧郁期、接受期"],"answer":3,"explanation":"库伯勒·罗斯提出临终心理五期：否认、愤怒、协议（讨价还价）、忧郁、接受。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2310","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"尸体护理时，头部应垫枕的目的是","options":["防止口腔张开","保持体位","防止面部淤血变色","便于辨认"],"answer":2,"explanation":"尸体护理头下垫枕可防止面部淤血变色，维持良好外观。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2311","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"尸体护理时，尸体识别卡应放置三处，不包括","options":["停尸房登记处","尸体手腕部","尸体腰部","尸屉外"],"answer":3,"explanation":"尸体识别卡分别放于手腕、腰部和尸屉外，无停尸房登记处一说。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2312","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病室适宜的温度为","options":["15～18℃","10～15℃","25～30℃","18～22℃"],"answer":3,"explanation":"一般病室温度18～22℃，新生儿及手术室为22～24℃，湿度50%～60%。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2313","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病室湿度过低时，病人可出现","options":["食欲下降","胸闷、憋气","肌肉酸痛","口干舌燥、咽痛"],"answer":3,"explanation":"湿度过低空气干燥，引起口干舌燥、咽痛；过高则感胸闷、憋气。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2314","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"铺备用床的目的是","options":["准备接收新病人","供麻醉术后病人使用","供病人休息","保护被褥"],"answer":0,"explanation":"备用床为接收新病人准备；麻醉床为术后病人准备，可防止污染床单位。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2315","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"麻醉床铺橡胶单、中单的目的是","options":["便于搬运","增加舒适","保暖","防止呕吐物、血液等污染床单位"],"answer":3,"explanation":"麻醉床铺橡胶单中单用于承接术后呕吐物、渗血渗液，保护床单位。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2316","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人翻身时，两人操作的正确方法是","options":["一人拖拽","两人分别扶托病人肩部和腰腿部，协调用力","仅移动上半身","先抬头部"],"answer":1,"explanation":"两人翻身应分段托扶肩背和腰臀腿部，保持脊柱平直，协调用力。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2317","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"协助病人翻身侧卧时，两膝间应","options":["交叉","并拢","伸直","垫软枕"],"answer":3,"explanation":"侧卧位时两膝间垫软枕，上腿弯曲下腿伸直，保持舒适稳定。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2318","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"半坐卧位适用于","options":["腹部手术后病人","休克病人","昏迷病人","脊柱损伤病人"],"answer":0,"explanation":"半坐卧位利于腹腔引流、减轻切口张力，适用于腹部术后及心肺疾病病人。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2319","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"休克病人宜采取的体位是","options":["中凹卧位（头胸10～20°，下肢20～30°）","平卧位","侧卧位","头低足高位"],"answer":0,"explanation":"休克病人取中凹卧位，增加回心血量并改善脑部血流。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2320","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"颅内压增高病人宜取","options":["中凹卧位","头低足高位","头高足低位","俯卧位"],"answer":2,"explanation":"头高足低位可降低颅内压，适用于颅脑术后及颅内压增高病人。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2321","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"保护具使用的原则是","options":["长期使用","知情同意、短期使用、随病情变化调整","惩罚性使用","随意使用"],"answer":1,"explanation":"保护具须取得家属知情同意，短期使用并定时松解，观察血运。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2322","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"约束带使用时，应观察的重点是","options":["局部血液循环","体温","血压","饮食"],"answer":0,"explanation":"使用约束带应每15～30分钟观察局部血运，每2小时松解一次。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2323","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"口腔护理的目的不包括","options":["清除口臭","预防感染","增进食欲","降低体温"],"answer":0,"explanation":"口腔护理用于保持口腔清洁、预防感染、观察口腔变化，不能降低体温。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2324","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为昏迷病人进行口腔护理时，应特别注意","options":["用力擦拭","棉球不可过湿，防止误吸","使用金属镊子","让病人漱口"],"answer":1,"explanation":"昏迷病人口腔护理棉球不可过湿，禁止漱口，防止误吸窒息。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2325","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"长期使用抗生素的病人易发生","options":["真菌感染","细菌性肺炎","病毒性感冒","寄生虫感染"],"answer":0,"explanation":"长期广谱抗生素抑制正常菌群，易致白色念珠菌等真菌二重感染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2326","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"口腔pH偏碱性时，宜选用","options":["0.9%氯化钠溶液","2%～3%硼酸溶液","1%～3%过氧化氢溶液","朵贝尔溶液"],"answer":0,"explanation":"pH偏碱性时选用硼酸溶液；偏酸性时用过氧化氢或朵贝尔液。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2327","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"晨间护理的时间一般在","options":["晚间","中午","清晨诊疗护理前","任意时间"],"answer":2,"explanation":"晨间护理于清晨诊疗护理前进行，包括洗漱、翻身、皮肤护理等。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2328","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"晚间护理的目的是","options":["帮助病人入睡","测量生命体征","采集标本","准备手术"],"answer":0,"explanation":"晚间护理创造安静环境，协助洗漱、调暗灯光，帮助病人入睡。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2329","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"采集静脉血标本时，正确的做法是","options":["从输液同侧肢体采血","先输液后采血","根据检验目的选择试管并按规定量采血","采血后剧烈摇动试管"],"answer":2,"explanation":"采血应避开输液侧肢体，按检验目的选试管，全血标本轻摇混匀防凝固。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2330","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"采集全血标本后应","options":["静置2小时","立即轻轻摇匀，防止凝血","加入防腐剂","冷藏后摇匀"],"answer":1,"explanation":"全血标本采后立即轻摇使抗凝剂与血液混匀，防止凝血。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2331","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"留取尿常规标本的正确时间是","options":["任意时间","晨起第一次尿","餐后2小时","睡前"],"answer":1,"explanation":"晨尿浓缩、不受饮食影响，检查结果准确，宜留晨起第一次尿约100ml。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2332","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"采集粪便寄生虫卵标本时，应","options":["混入尿液","取粪便表面任意部分","整块送检","取不同部位带黏液或脓血部分"],"answer":3,"explanation":"寄生虫卵检查应在粪便不同部位取带黏液脓血部分5～10g送检。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2333","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"阿米巴痢疾病人留取粪便标本时，应","options":["冷藏后送检","便盆加温至接近体温后立即送检","加入防腐剂","干燥后送检"],"answer":1,"explanation":"阿米巴原虫在低温下失去活动力，标本便盆需加温并立即送检。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2334","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"采集痰培养标本时，正确的做法是","options":["清晨漱口后深咳出气管深部痰液","留取口水","餐后立即留取","混入鼻涕"],"answer":0,"explanation":"痰培养应于清晨漱口后深咳留取气管深部痰液，防止口腔杂菌污染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2335","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为休克病人留置导尿的主要目的是","options":["监测每小时尿量，判断肾功能","预防感染","减轻痛苦","采集标本"],"answer":0,"explanation":"休克病人留置导尿监测每小时尿量，作为补液和病情判断的重要指标。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2336","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"膀胱冲洗的目的不包括","options":["治疗膀胱疾病","预防感染","保持引流通畅","增加尿量"],"answer":2,"explanation":"膀胱冲洗用于保持通畅、预防感染、治疗膀胱疾病，不能直接增加尿量。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2337","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"冷敷治疗扭伤早期的作用是","options":["促进淤血吸收","减轻局部充血、出血和疼痛","增加渗出","升高局部温度"],"answer":1,"explanation":"扭伤24小时内冷敷使血管收缩，减轻充血出血和疼痛；48小时后热敷促进吸收。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2338","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"热疗的禁忌证不包括","options":["面部危险三角区感染","软组织扭伤48小时内","出血性疾病","慢性腰痛"],"answer":1,"explanation":"慢性腰痛可热疗促进循环；扭伤早期、面部三角区感染、出血倾向均为热疗禁忌。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2339","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"面部危险三角区感染禁用热疗的原因是","options":["易致面部肿胀","易致颅内感染","影响呼吸","引起过敏"],"answer":1,"explanation":"三角区血管与颅内相通，热疗使细菌入颅，引起颅内感染。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2340","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"热水坐浴的水温为","options":["室温","30℃","50℃以上","40～45℃"],"answer":3,"explanation":"热水坐浴水温40～45℃，坐浴时间15～20分钟，用于会阴、肛门疾病。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2341","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行乙醇拭浴时，出现寒战、面色苍白应","options":["加大乙醇浓度","继续擦浴","加快速度","立即停止擦浴，注意保暖"],"answer":3,"explanation":"擦浴中出现寒战、面色苍白、脉搏异常应立即停止并保暖，防止虚脱。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2342","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"鼻饲前应确认胃管在胃内的方法不包括","options":["听气过水声","回抽胃液","让病人说话","观察有无呛咳"],"answer":2,"explanation":"确认胃管在胃内的方法：回抽胃液、听气过水声、观察气泡，不能让病人说话判断。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2343","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"更换鼻饲胃管的时间为","options":["每2周更换","每日更换","每月更换","每周更换一次"],"answer":3,"explanation":"普通胃管每周更换一次，硅胶胃管每月更换一次，晚间末次喂食后拔出，晨起插入。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2344","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输液中茂菲滴管液面过低时，正确处理是","options":["拔针重输","更换输液器","捏紧滴管上端，挤入适量液体","调高滴管"],"answer":2,"explanation":"滴管液面过低可捏紧上端导管挤压滴管，使液面升至1/3～1/2处。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2345","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输液速度的调节依据不包括","options":["药物性质","年龄","病情","病人的体重"],"answer":3,"explanation":"输液速度依据年龄、病情、药物性质调节，体重不是常规依据。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2346","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心功能不全病人输液速度应","options":["宜快","宜慢，20～30滴/分","正常","先快后慢"],"answer":1,"explanation":"心功能不全者输液宜慢，防止加重心脏负荷诱发肺水肿。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2347","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"静脉输血前，血制品在室温下放置时间不超过","options":["1小时","2小时","30分钟","5分钟"],"answer":2,"explanation":"血液制品取回后应在30分钟内输注，室温放置不超过30分钟。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2348","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输血开始时应","options":["先慢速观察15分钟无反应再调至正常速度","快速输入","直接全速输入","间断输入"],"answer":0,"explanation":"输血开始15分钟内慢速观察有无反应，无异常再调至正常滴速。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2349","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"PICC导管维护时冲管液一般选用","options":["生理盐水10ml以上","蒸馏水","5%葡萄糖","抗生素溶液"],"answer":0,"explanation":"PICC维护用10ml以上生理盐水脉冲式冲管，防止堵管。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2350","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"PICC置管后应观察的内容不包括","options":["导管外露长度","手臂有无肿胀","穿刺点有无渗血","病人的鞋码"],"answer":2,"explanation":"PICC观察穿刺点、肢体肿胀、导管外露长度等，与鞋码无关。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2351","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"化疗药物外渗时，正确的处理是","options":["按摩","热敷","继续输入","立即停止输液并回抽，局部冷敷"],"answer":3,"explanation":"化疗药外渗应立即停止输注、回抽药液、局部冷敷（除个别药物外），报告医生。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2352","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输液泵报警常见原因不包括","options":["气泡","药液将尽","输液管堵塞","病人饥饿"],"answer":2,"explanation":"输液泵报警由堵塞、气泡、药液将尽等引起，与饥饿无关。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2353","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为气管切开病人吸痰时，正确的顺序是","options":["随意顺序","先吸口鼻","先吸气管套管内，再吸口鼻部","先吸鼻腔后吸套管"],"answer":2,"explanation":"气管切开吸痰先吸套管内痰液，再吸口鼻，防止污染气道。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2354","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气管切开病人内套管消毒的方法是","options":["酒精灯烧灼","煮沸或浸泡消毒后清水冲净","直接使用","高压蒸汽灭菌全部套管"],"answer":1,"explanation":"气管内套管可煮沸或浸泡消毒，外套管不必每日高压灭菌。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2355","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气切病人吸氧时，宜使用","options":["气切面罩或头罩","鼻导管","鼻塞","普通面罩"],"answer":0,"explanation":"气管切开病人经套管吸氧，宜用气切面罩，不能经鼻导管给氧。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2356","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为卧床病人更换床单时，正确的做法是","options":["快速掀开全部被褥","动作轻稳，注意保暖，避免过多暴露","不考虑病人感受","先撤枕头"],"answer":1,"explanation":"更换床单应动作轻稳、注意保暖遮挡，避免过多暴露病人。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2357","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"协助病人由床向平车移动时，平车与床的位置应","options":["随意摆放","呈直角","平齐，头端朝床头方向","头端朝床尾"],"answer":2,"explanation":"平车与床平行紧靠，搬运时保持病人头部在先，防止损伤。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2358","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"使用平车运送输液病人时，应注意","options":["拔除输液","保持输液通畅，防止针头脱出","夹闭输液管","加快滴速"],"answer":1,"explanation":"平车搬运输液病人应保持输液通畅，防止针头移位脱落。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2359","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人测量体温时，发现体温与病情不符应","options":["直接记录","重新测量并核对","让家属复测","忽略"],"answer":1,"explanation":"体温与病情不符应重新测量核对，必要时测肛温对照。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2360","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测量肛温时，润滑肛表插入肛门的深度为","options":["7cm","1cm","5～6cm","3～4cm"],"answer":3,"explanation":"肛温测量润滑后插入肛门3～4cm，测量3分钟。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2361","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脉搏短绌的病人测量方法为","options":["单人测1分钟脉率","两人同时测心率与脉率，测1分钟","测30秒乘2","只测心率"],"answer":1,"explanation":"脉搏短绌需两人同时测量心率与脉率各1分钟，以心率记录。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2362","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"呼吸过缓是指成人呼吸频率低于","options":["12次/分","16次/分","10次/分","8次/分"],"answer":0,"explanation":"成人呼吸频率低于12次/分为呼吸过缓，高于24次/分为呼吸过速。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2363","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"潮式呼吸的特点是","options":["呼吸浅快","呼吸深大规则","呼吸由浅慢逐渐深快再变浅慢，暂停后周而复始","呼吸与暂停交替无规律"],"answer":2,"explanation":"潮式（陈-施）呼吸呈周期性由浅慢到深快再变浅慢，随后暂停。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2364","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"库斯莫尔呼吸常见于","options":["肺气肿","支气管哮喘","糖尿病酮症酸中毒","胸腔积液"],"answer":2,"explanation":"代谢性酸中毒时出现深大规则的库斯莫尔呼吸，常见于糖尿病酮症酸中毒。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2365","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"三凹征是指","options":["胸骨上窝、锁骨上窝、肋间隙凹陷","鼻翼、口唇、指端发绀","颈静脉、肝颈静脉、下肢水肿","眼窝、腋窝、腹股沟凹陷"],"answer":0,"explanation":"三凹征为吸气性呼吸困难的典型体征，见于喉头水肿、气管异物等上呼吸道梗阻。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2366","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行鼻导管给氧时，插入深度为","options":["5cm","鼻尖至耳垂的1/3","鼻尖至耳垂全长","鼻尖至耳垂的2/3"],"answer":3,"explanation":"单侧鼻导管给氧插入长度为鼻尖至耳垂的2/3，约10～15cm。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2367","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"氧气筒内氧气不可用尽的原因是","options":["节约成本","防止灰尘杂质进入筒内引起爆炸","保持压力恒定","防止漏气"],"answer":1,"explanation":"氧气用尽后杂质进入筒内，再次充氧时可能引起爆炸，应保留0.5MPa余压。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2368","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"氧气表上的减压器作用是","options":["过滤氧气","增加氧气流量","将筒内高压氧气降至适宜压力","加热氧气"],"answer":2,"explanation":"减压器将氧气筒内高压降至0.2～0.3MPa便于使用。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2369","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人吸痰前应","options":["先深插后开机","直接插入吸引","先调节负压，试吸通畅后再插入","关闭负压吸引"],"answer":2,"explanation":"吸痰前调节负压（成人40～53.3kPa），试吸通畅后再插入吸引。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2370","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为气管插管病人吸痰时，正确的做法是","options":["不给氧","吸痰中给氧","吸痰前后给予高浓度氧气吸入","先吸痰后给氧"],"answer":2,"explanation":"吸痰前后给予高浓度氧2～3分钟，防止低氧血症。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2371","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行心肺复苏时，按压有效的指征不包括","options":["自主呼吸恢复","面色转红","可触及大动脉搏动","瞳孔散大"],"answer":3,"explanation":"按压有效表现为面色转红、大动脉搏动、瞳孔缩小、自主呼吸恢复，瞳孔散大为无效表现。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2372","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"复苏后病人体位宜取","options":["侧卧位","头低足高位","仰卧位，头部略抬高","俯卧位"],"answer":2,"explanation":"复苏后宜仰卧位、头部略抬高，利于脑部血液回流。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2373","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为危重病人眼睑不能闭合者，应","options":["不予处理","滴入抗生素","用生理盐水冲洗","涂眼药膏并覆盖纱布"],"answer":3,"explanation":"眼睑不能闭合者涂眼膏并覆盖纱布，保护角膜防止干燥感染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2374","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"危重病人护理记录书写要求不包括","options":["完整","客观准确","及时","记录主观猜测"],"answer":3,"explanation":"护理记录应客观、及时、完整、规范，不得主观猜测。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2375","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为昏迷病人翻身时，应注意","options":["保持呼吸道通畅，防止误吸","先喂水","抬高头部","快速翻身"],"answer":0,"explanation":"昏迷病人翻身应保持呼吸道通畅，防止舌后坠和误吸。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2376","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为长期卧床病人进行皮肤护理的目的是","options":["预防压疮","促进消化","增加体重","改善睡眠"],"answer":0,"explanation":"长期卧床皮肤护理重点是保持清洁干燥、促进循环，预防压疮。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2377","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行晨间护理时，发现皮肤发红应","options":["增加翻身次数，避免局部受压","用力按摩","热敷","涂酒精"],"answer":0,"explanation":"皮肤发红为压疮早期表现，应增加翻身、避免受压，不宜用力按摩。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2378","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人测量血压时，发现血压听不清应","options":["立即重测","驱尽袖带气体，间隔片刻重测","换侧肢体","记录为0"],"answer":1,"explanation":"血压听不清应驱尽袖带内气体，汞柱降至零，间隔1～2分钟再测。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2379","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为偏瘫病人测量血压时，应选择","options":["下肢","患侧上肢","双上肢","健侧上肢"],"answer":3,"explanation":"偏瘫病人应在健侧测量，患侧循环差，结果不准确。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2380","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行静脉输液时，发现局部肿胀、疼痛应","options":["减慢滴速","立即停止输液，拔针并处理","继续输入","热敷后继续"],"answer":1,"explanation":"输液局部肿胀疼痛提示药液外渗，应立即停止输液拔针，按药液性质处理。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2381","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行肌肉注射时，进针后应","options":["回抽无血后再推药","直接推药","边推边抽","先推药后回抽"],"answer":0,"explanation":"肌注进针后应回抽确认无血，防止药液误入血管。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2382","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行皮内注射时，正确的做法是","options":["注射后勿按压","用力按压","按摩局部","冰敷"],"answer":0,"explanation":"皮内注射后勿按压、勿揉擦，以免影响皮试结果。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2383","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行皮下注射胰岛素时，注射部位应","options":["定期轮换","固定一处","随意选择","避开腹部"],"answer":0,"explanation":"胰岛素注射应定期轮换部位，防止脂肪萎缩和吸收异常。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2384","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行雾化吸入后，应","options":["漱口并洗脸","立即进食","平卧","饮水后平卧"],"answer":0,"explanation":"雾化吸入含激素类药物后应漱口洗脸，防止口腔真菌感染和面部药物残留。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2385","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行导尿时，动作应","options":["轻柔，防止损伤尿道黏膜","快速插入","用力插入","反复插入"],"answer":0,"explanation":"导尿应轻柔操作，防止尿道黏膜损伤和感染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2386","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行灌肠时，如出现面色苍白、出冷汗应","options":["抬高灌肠筒","减慢速度","继续灌肠","立即停止灌肠并通知医生"],"answer":3,"explanation":"灌肠中出现面色苍白、出冷汗、剧烈腹痛应立即停止，通知医生处理。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2387","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行冷敷时，应观察的内容不包括","options":["皮肤有无冻伤","局部皮肤颜色","病人感觉","病人的饮食"],"answer":3,"explanation":"冷敷观察局部皮肤、感觉及有无冻伤，与饮食无关。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2388","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行热敷时，水温不宜超过","options":["80℃","70℃","50℃（特殊人群）","40℃"],"answer":2,"explanation":"热敷水温一般60～70℃，婴幼儿、老人、循环障碍者不超过50℃，防止烫伤。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2389","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行口腔护理时，发现口腔黏膜溃疡应","options":["用热水含漱","用酒精擦拭","涂西瓜霜或锡类散","不予处理"],"answer":2,"explanation":"口腔溃疡可涂西瓜霜、锡类散或溃疡膏，促进愈合。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2390","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行皮肤护理时，应重点检查","options":["骨隆突处皮肤","四肢","腹部","背部全部"],"answer":0,"explanation":"骨隆突处为压疮好发部位，应重点检查受压皮肤。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2391","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行晨间护理时，应协助","options":["外出","进食","运动","洗漱、翻身、整理床单位"],"answer":3,"explanation":"晨间护理包括协助洗漱、翻身、皮肤护理、整理床单位等。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2392","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行晚间护理时，应","options":["调暗灯光，保持病室安静","开灯照明","大声说话","增加探视"],"answer":0,"explanation":"晚间护理应调暗灯光、保持安静，协助病人入睡。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2393","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行鼻饲时，每次喂食前应","options":["直接注入","回抽胃液确认胃管在胃内","先注入温水","先注入药物"],"answer":1,"explanation":"鼻饲前回抽胃液确认胃管位置，防止误吸。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2394","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行氧气吸入时，应先","options":["调节氧流量后再插入鼻导管","先插管后调流量","随意顺序","关闭氧气"],"answer":0,"explanation":"先调流量后插管，防止大量氧气冲击呼吸道黏膜。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2395","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人停用氧气时，应先","options":["先关氧气","取下鼻导管再关氧气开关","随意顺序","拔管后关表"],"answer":1,"explanation":"停氧应先取下鼻导管再关氧气开关，防止关表不当致氧气外冲损伤呼吸道。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2396","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行心肺复苏时，按压深度为","options":["7～8cm","2～3cm","5～6cm","3～4cm"],"answer":2,"explanation":"成人CPR按压深度5～6cm，频率100～120次/分，保证胸廓充分回弹。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2397","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行海姆立克急救时，冲击部位为","options":["脐上两横指处","脐下","胸骨","背部"],"answer":0,"explanation":"海姆立克法冲击部位为腹部脐上两横指处，向内向上冲击。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2398","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行急救时，应遵循的原则是","options":["先救命后治病","先治病后救命","先转运后抢救","先检查后抢救"],"answer":0,"explanation":"急救原则为先救命后治病，优先处理危及生命的问题。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2399","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行转运时，应","options":["拔除所有管路","保持呼吸道通畅，妥善固定管路","随意搬运","不考虑体位"],"answer":1,"explanation":"转运危重病人应保持呼吸道通畅、妥善固定管路、防止脱出。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2400","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行出院指导时，应包括","options":["仅饮食","仅用药","用药、饮食、复诊及功能锻炼","仅复诊"],"answer":2,"explanation":"出院指导应全面，包括用药、饮食、活动、复诊等。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2401","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行入院介绍时，应介绍","options":["仅医生姓名","仅病房号","病区环境、规章制度、主管医护人员","仅护士站位置"],"answer":2,"explanation":"入院介绍包括病区环境、安全、制度、主管医生护士等，帮助病人适应。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2402","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行健康宣教时，应","options":["一律书面","一律口头","根据病人文化程度和理解能力选择方式","不考虑病人情况"],"answer":2,"explanation":"健康宣教应个体化，根据病人文化程度、接受能力选择合适方式。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2403","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行心理护理时，应","options":["倾听、共情，建立信任关系","说教","回避","批评"],"answer":0,"explanation":"心理护理以倾听、共情、支持为主，建立良好护患关系。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2404","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行疼痛评估时，常用的方法是","options":["数字评分法","观察法","询问家属","猜测"],"answer":0,"explanation":"疼痛评估常用数字评分法（NRS）、面部表情量表等，以病人主诉为准。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2405","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行营养评估时，应包括","options":["仅进食","仅体重","体重、进食情况、实验室指标","仅身高"],"answer":2,"explanation":"营养评估包括体重变化、进食情况、生化指标等综合判断。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2406","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行跌倒风险评估时，应包括","options":["仅身高","仅年龄","仅性别","年龄、用药史、既往跌倒史、平衡能力"],"answer":3,"explanation":"跌倒风险评估包括年龄、用药、既往史、平衡能力、环境等多因素。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2407","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行压疮风险评估时，常用的量表是","options":["Braden量表","GCS量表","VAS量表","APGAR量表"],"answer":0,"explanation":"压疮风险常用Braden量表；GCS为昏迷评分，VAS为疼痛评分。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2408","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行跌倒预防宣教时，应告知","options":["快速起床","起床时遵循“三部曲”，动作缓慢","穿拖鞋","不扶扶手"],"answer":1,"explanation":"预防跌倒应遵循起床三部曲（醒后躺30秒、坐30秒、站30秒），穿防滑鞋。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2409","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行管路护理时，应","options":["随意放置","妥善固定，防止脱出","不固定","自行拔除"],"answer":1,"explanation":"管路护理应妥善固定、标识清晰、防止脱出，观察引流情况。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2410","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行输血时，应","options":["单人核对","双人核对血型和病人信息","家属核对","医生核对"],"answer":1,"explanation":"输血必须双人核对血型、交叉配血结果及病人信息，确保安全。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2411","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行化疗时，应","options":["监测血常规，观察不良反应","仅观察体温","不监测","仅观察血压"],"answer":0,"explanation":"化疗期间监测血常规、肝肾功能，观察恶心、脱发等不良反应。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2412","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行术后护理时，应","options":["仅观察伤口","观察生命体征、伤口及引流情况","仅观察体温","仅观察血压"],"answer":1,"explanation":"术后护理应观察生命体征、伤口、引流、疼痛及并发症等。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2413","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行术前护理时，应","options":["仅禁食","隐瞒手术信息","仅备皮","讲解手术流程，进行适应性训练"],"answer":3,"explanation":"术前护理包括健康宣教、心理支持、适应性训练、备皮、禁食等。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2414","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行禁食护理时，应","options":["喂水","不予处理","让病人漱口","口腔护理每日2次"],"answer":3,"explanation":"禁食病人应做好口腔护理，防止口腔感染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2415","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行输液时，发现液体不滴应","options":["检查针头是否堵塞、脱出或体位不当","立即拔针","加快滴速","用力挤压"],"answer":0,"explanation":"液体不滴应查找原因：针头滑出、堵塞、体位不当或压力不足，对症处理。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2416","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行输血时，发现溶血反应应","options":["减慢速度","立即停止输血，保留静脉通路","继续输血","更换血袋继续"],"answer":1,"explanation":"溶血反应应立即停止输血，保留静脉通路，报告医生并抢救。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2417","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行氧气吸入时，湿化瓶应","options":["不更换","每周更换","每日更换湿化液","每月更换"],"answer":2,"explanation":"湿化瓶每日更换灭菌水，定期消毒，防止细菌滋生。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2418","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行吸痰时，负压成人一般为","options":["20kPa","40～53.3kPa","60kPa","70kPa"],"answer":1,"explanation":"成人吸痰负压40～53.3kPa，儿童33.3～40kPa。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2419","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行气管切开护理时，应","options":["减少护理","不吸痰","保持套管通畅，及时吸痰","仅换纱布"],"answer":2,"explanation":"气切护理应保持套管通畅、及时吸痰、清洁消毒内套管、更换敷料。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2420","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人进行鼻饲时，发现胃液呈咖啡色应","options":["继续鼻饲","暂停鼻饲并报告医生","加快速度","减少量"],"answer":1,"explanation":"咖啡色胃液提示消化道出血，应暂停鼻饲并报告医生。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2421","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中医学的基本特点是","options":["整体观念和辨证论治","阴阳五行","望闻问切","精气学说"],"answer":0,"explanation":"中医学两大基本特点为整体观念与辨证论治。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2422","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"阴阳的基本含义是","options":["指天地","指太阳和月亮","对自然界相互关联的某些事物和现象对立双方的概括","指水火"],"answer":2,"explanation":"阴阳是宇宙中相互关联又相互对立的事物或现象属性的概括。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2423","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"“阴平阳秘，精神乃治”说明","options":["阴阳平衡是维持正常生命活动的基础","阴气要旺盛","阳气要旺盛","阴阳相互对立"],"answer":0,"explanation":"阴阳处于动态平衡，人体才能健康。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2424","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"五行中“土”的特性是","options":["生化、承载、受纳","生长、升发","收敛","寒凉滋润"],"answer":0,"explanation":"土性生化承载，主万物之化育。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2425","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"五行相生的顺序是","options":["木生火，火生土，土生金，金生水，水生木","木克土，土克水","水生木，木生土","火克金，金克木"],"answer":0,"explanation":"五行相生：木→火→土→金→水→木。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2426","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"五行相克的顺序是","options":["水克土","木克火","土克木","木克土，土克水，水克火，火克金，金克木"],"answer":3,"explanation":"五行相克：木克土、土克水、水克火、火克金、金克木。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2427","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心在五行属","options":["金","水","木","火"],"answer":3,"explanation":"心属火，肝属木，脾属土，肺属金，肾属水。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2428","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"“肺主一身之气”取决于","options":["肺的肃降","肺的宣发","肺的呼吸功能","肺朝百脉"],"answer":2,"explanation":"肺通过呼吸运动生成宗气，主一身之气。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2429","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脾主运化是指","options":["脾主肌肉","脾具有运化水谷精微和水液的功能","脾统血","脾主升清"],"answer":1,"explanation":"脾主运化包括运化水谷和运化水液两方面。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2430","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾主水是指","options":["肾主纳气","肾藏精","肾具有主持和调节全身水液代谢的功能","肾主骨"],"answer":2,"explanation":"肾阳的气化作用主宰全身水液代谢。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2431","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝主疏泄的功能不包括","options":["促进消化","调畅气机","调节情志","统摄血液"],"answer":3,"explanation":"肝主疏泄包括调畅气机、调节情志、促进消化，统血为脾的功能。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2432","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"称为“后天之本”的是","options":["心","肾","脾","肺"],"answer":2,"explanation":"脾主运化水谷，为气血生化之源，称后天之本；肾为先天之本。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2433","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"称为“水脏”的是","options":["肺","脾","肾","膀胱"],"answer":2,"explanation":"肾主水，为水脏；膀胱为水腑。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2434","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"“肺为水之上源”是因为","options":["肺主宣发肃降，通调水道","肺主气","肺朝百脉","肺主皮毛"],"answer":0,"explanation":"肺通过宣发肃降调节水液输布和排泄，故称水之上源。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2435","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气血关系正确的是","options":["血能生气","气能生血、行血、摄血，血能载气","气能载血","二者无关"],"answer":1,"explanation":"气为血之帅，血为气之母，气血相互依存。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2436","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"“气为血之帅”是指","options":["血能载气","气能生血、行血、摄血","血能养气","气血同源"],"answer":1,"explanation":"气能推动和统摄血液运行，故称气为血之帅。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2437","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"津液的输布主要依靠","options":["脾肺肾肝等脏腑的协同作用","仅脾","仅肺","仅肾"],"answer":0,"explanation":"津液代谢依赖脾的转输、肺的宣降、肾的蒸腾气化等协同。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2438","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"经络系统中，十二经脉的命名依据不包括","options":["脏腑","阴阳","手足","五行"],"answer":1,"explanation":"十二经脉以手足、阴阳、脏腑命名，与五行无直接命名关系。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2439","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"十二经脉中，循行于上肢外侧前缘的是","options":["手太阴肺经","手阳明大肠经","手少阳三焦经","手太阳小肠经"],"answer":1,"explanation":"手阳明大肠经行于上肢外侧前缘。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2440","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"奇经八脉中，称为“血海”的是","options":["冲脉","任脉","督脉","带脉"],"answer":0,"explanation":"冲脉为血海；督脉为阳脉之海；任脉为阴脉之海。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2441","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"称为“阳脉之海”的是","options":["冲脉","督脉","带脉","阳跷脉"],"answer":1,"explanation":"督脉总督一身之阳经，为阳脉之海。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2442","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"六淫中，具有“善行数变”特点的是","options":["湿邪","寒邪","风邪","燥邪"],"answer":2,"explanation":"风邪善行数变，为百病之长，常兼夹他邪致病。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2443","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"湿邪的性质和致病特点不包括","options":["黏滞","重浊","易伤津液","易阻气机"],"answer":2,"explanation":"湿邪重浊黏滞、易阻遏气机、易伤脾阳；燥邪才易伤津液。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2444","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"七情致病最易损伤的脏腑是","options":["胆、胃","肺、肾","大肠、小肠","心、肝、脾"],"answer":3,"explanation":"七情过激主要伤及心、肝、脾三脏。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2445","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"“望神”中，病人表现为精神不振、面色少华属于","options":["假神","得神","失神","少神"],"answer":3,"explanation":"少神（神气不足）见于轻度失养或体虚；失神为精气亏损危重。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2446","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病人面色苍白或晦暗、精神萎靡、目光呆滞属于","options":["得神","失神","少神","神志清楚"],"answer":1,"explanation":"失神为精气衰败，病情危重之象。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2447","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"久病重病者突然精神转佳、颧红如妆属于","options":["少神","得神","假神","正常"],"answer":2,"explanation":"假神为阴阳离决前的回光返照，提示病情恶化。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2448","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常人面色为","options":["红黄隐隐，明润含蓄","苍白","萎黄","晦暗"],"answer":0,"explanation":"正常面色红黄隐隐、明润含蓄，为有胃气、有神气之象。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2449","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"面色发黄多主","options":["热证","寒证","痛证","脾虚、湿证"],"answer":3,"explanation":"黄色主脾虚、湿证；白色主寒证、失血；青色主寒、痛、瘀血。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2450","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"舌诊中，舌质的正常表现是","options":["淡白","深红","紫暗","淡红润泽"],"answer":3,"explanation":"正常舌质淡红润泽，苔薄白。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2451","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"舌苔白腻多提示","options":["热盛","痰湿内停","瘀血","阴虚"],"answer":1,"explanation":"白腻苔主痰湿、寒湿内停。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2452","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"舌红少苔或无苔多提示","options":["血瘀","寒湿","气虚","阴虚内热"],"answer":3,"explanation":"舌红少苔为阴虚火旺之象。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2453","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"问诊中，问寒热的类型不包括","options":["寒热错杂","恶寒发热","但热不寒","寒热往来"],"answer":3,"explanation":"问寒热包括恶寒发热、但寒不热、但热不寒、寒热往来，无“寒热错杂”类型。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2454","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"潮热的特点是","options":["按时发热或定时热甚，如潮汐","持续高热","低热不断","寒战"],"answer":0,"explanation":"潮热按时发热或定时热甚，有阴虚潮热、阳明潮热等类型。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2455","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"切脉的部位一般选择","options":["耳前动脉","足背动脉","颈动脉","寸口脉（桡动脉）"],"answer":3,"explanation":"切脉以寸口脉（腕部桡动脉）为主，分寸关尺三部。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2456","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常脉象的特点是","options":["一息六至以上","三部有脉，一息四至，不浮不沉","脉细如线","脉来结代"],"answer":1,"explanation":"平脉一息四至五至，从容和缓，节律一致。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2457","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脉象“浮脉”主","options":["表证","里证","寒证","虚证"],"answer":0,"explanation":"浮脉主表证，外邪袭表，脉浮而有力。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2458","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脉象“沉脉”主","options":["热证","表证","里证","风证"],"answer":2,"explanation":"沉脉主里证，病邪在里，脉沉。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2459","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"八纲辨证是指","options":["六经、卫气营血","气血、津液","脏腑、经络","阴阳、表里、寒热、虚实"],"answer":3,"explanation":"八纲为阴阳、表里、寒热、虚实，是辨证的总纲。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2460","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"实证的临床表现不包括","options":["神疲乏力","疼痛拒按","脉实有力","舌苔厚腻"],"answer":0,"explanation":"神疲乏力为虚证表现；实证多见疼痛拒按、脉实有力等。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2461","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"阴虚证的临床表现是","options":["面色苍白","畏寒肢冷","五心烦热、潮热盗汗、舌红少苔","脉沉迟"],"answer":2,"explanation":"阴虚证见五心烦热、潮热盗汗、口干咽燥、舌红少苔、脉细数。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2462","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"阳虚证的临床表现是","options":["潮热盗汗","五心烦热","畏寒肢冷、面色苍白、脉沉迟无力","舌红少苔"],"answer":2,"explanation":"阳虚证见畏寒肢冷、面色苍白、神疲乏力、脉沉迟无力。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2463","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气虚证的临床表现是","options":["脉细数","五心烦热","潮热盗汗","神疲乏力、气短懒言、自汗"],"answer":3,"explanation":"气虚证见神疲乏力、气短懒言、自汗、舌淡脉虚无力。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2464","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"血虚证的临床表现是","options":["面色苍白或萎黄、头晕眼花、心悸","五心烦热","潮热盗汗","脉滑数"],"answer":0,"explanation":"血虚证见面色苍白或萎黄、唇甲色淡、头晕心悸、脉细。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2465","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脏腑辨证中，心气虚的典型表现是","options":["心悸、气短、活动后加重","咳嗽","腹泻","腰膝酸软"],"answer":0,"explanation":"心气虚见心悸气短、活动后加重、神疲乏力。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2466","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺气虚的典型表现是","options":["五心烦热","心悸","腹泻","咳喘无力、气短、自汗畏风"],"answer":3,"explanation":"肺气虚见咳喘无力、气短声低、自汗畏风、易感冒。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2467","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脾胃虚寒的典型表现是","options":["五心烦热","腹痛拒按","便秘","腹痛喜温喜按、大便稀溏"],"answer":3,"explanation":"脾胃虚寒见腹痛绵绵、喜温喜按、食少便溏、畏寒肢冷。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2468","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾阳虚的典型表现是","options":["腰膝酸冷、畏寒肢冷、夜尿多","五心烦热","潮热盗汗","舌红少苔"],"answer":0,"explanation":"肾阳虚见腰膝酸冷、畏寒肢冷、夜尿频多、舌淡苔白。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2469","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药四气是指","options":["升、降、浮、沉","酸、苦、甘、辛","寒、热、温、凉","归经"],"answer":2,"explanation":"中药四气（四性）为寒热温凉；五味为酸苦甘辛咸。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2470","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药五味中，具有“补益、和中、缓急”作用的是","options":["辛味","酸味","苦味","甘味"],"answer":3,"explanation":"甘味能补益、和中、缓急；辛味能散能行；酸味能收能涩。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2471","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药五味中，具有“发散、行气、行血”作用的是","options":["酸味","甘味","辛味","咸味"],"answer":2,"explanation":"辛味能散、能行，用于发散表邪、行气活血。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2472","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药“归经”是指","options":["药物的毒性","药物的产地","药物的采收时间","药物对某脏腑经络的选择性作用"],"answer":3,"explanation":"归经指药物作用对机体某部分（脏腑经络）的选择性。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2473","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药煎煮时，需要先煎的药物是","options":["砂仁","薄荷","矿物类、贝壳类药材","钩藤"],"answer":2,"explanation":"矿物、贝壳类质地坚硬，有效成分不易煎出，需先煎30分钟以上。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2474","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药煎煮时，需要后下的药物是","options":["龙骨","石膏","气味芳香的解表药","牡蛎"],"answer":2,"explanation":"薄荷、砂仁等芳香易挥发药物宜后下，煎煮5分钟左右。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2475","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药煎煮时，需要包煎的药物是","options":["附子","人参","车前子、旋覆花","大黄"],"answer":2,"explanation":"细小种子类和有绒毛的药物需包煎，防止浑浊或刺激咽喉。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2476","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中药煎煮时，需要烊化的药物是","options":["阿胶","黄连","黄芩","黄柏"],"answer":0,"explanation":"胶类药材如阿胶需烊化（隔水炖化）后兑入药汁。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2477","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"汤剂服药时间，一般","options":["睡前","立即饭后","饭前或饭后1小时左右","空腹"],"answer":2,"explanation":"汤剂一般饭前或饭后1小时服用，对胃肠刺激大的药物宜饭后服。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2478","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"驱虫药宜在","options":["空腹时服用","饭后服用","睡前服用","随时服用"],"answer":0,"explanation":"驱虫药宜空腹服，使药物迅速入肠，利于驱虫。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2479","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"安神药宜在","options":["睡前服用","晨起服用","饭前服用","饭后服用"],"answer":0,"explanation":"安神药宜睡前半小时至1小时服用，利于入睡。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2480","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"方剂中“君药”是指","options":["用量最大的药","针对主病或主证起主要治疗作用的药物","辅助君药的药","调和诸药的药"],"answer":1,"explanation":"君药针对主病主证起主要作用，为方剂核心。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2481","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"方剂组成中“使药”的作用是","options":["引经或调和诸药","主要治疗","辅助治疗","直接攻邪"],"answer":0,"explanation":"使药起引经报使或调和诸药的作用。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2482","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"银翘散的功用是","options":["泻下通便","辛温解表","辛凉透表，清热解毒","温补阳气"],"answer":2,"explanation":"银翘散为辛凉解表代表方，主治风热感冒。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2483","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"麻黄汤的组成不包括","options":["石膏","杏仁","桂枝","麻黄"],"answer":2,"explanation":"麻黄汤由麻黄、桂枝、杏仁、甘草组成，无石膏。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2484","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"四君子汤的功用是","options":["益气健脾","补血养血","滋阴降火","温阳散寒"],"answer":0,"explanation":"四君子汤（人参、白术、茯苓、甘草）为益气健脾基础方。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2485","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"四物汤的组成是","options":["人参、白术、茯苓、甘草","当归、川芎、白芍、熟地黄","黄芪、当归","熟地黄、山萸肉"],"answer":1,"explanation":"四物汤为补血调血基础方，由当归、川芎、白芍、熟地组成。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2486","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"补中益气汤的功用是","options":["温阳利水","清热解毒","滋阴补肾","补中益气，升阳举陷"],"answer":3,"explanation":"补中益气汤补中益气、升阳举陷，主治脾胃气虚及气虚下陷证。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2487","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"六味地黄丸的功用是","options":["温补肾阳","滋阴补肾","益气健脾","清热泻火"],"answer":1,"explanation":"六味地黄丸为滋阴补肾代表方，主治肾阴虚证。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2488","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾气丸的功用是","options":["滋阴降火","温补肾阳","益气固表","清热利湿"],"answer":1,"explanation":"肾气丸（金匮肾气丸）温补肾阳，主治肾阳不足证。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2489","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"针灸学中，手三阴经的循行方向是","options":["从头走足","从手走胸","从手走头","从胸走手"],"answer":3,"explanation":"手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2490","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"足三阴经的循行方向是","options":["从足走头","从腹走足","从足走腹","从头走足"],"answer":2,"explanation":"足三阴经从足走腹（胸），交手三阴经。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2491","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"常用的腧穴定位方法不包括","options":["骨度分寸法","五行定位法","体表标志法","手指同身寸法"],"answer":1,"explanation":"腧穴定位常用骨度分寸、体表标志、手指同身寸和简便取穴法，无五行定位法。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2492","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"合谷穴位于","options":["腕横纹上","手背第1、2掌骨之间","肘横纹处","肩部"],"answer":1,"explanation":"合谷穴位于手背第1、2掌骨间，第2掌骨桡侧中点处。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2493","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"足三里穴位于","options":["犊鼻下3寸","犊鼻下5寸","内踝上3寸","脐下3寸"],"answer":0,"explanation":"足三里位于犊鼻（外膝眼）下3寸，胫骨前嵴外一横指处。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2494","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"三阴交穴位于","options":["足背","外踝尖上3寸","内踝尖上5寸","内踝尖上3寸"],"answer":3,"explanation":"三阴交位于内踝尖上3寸，胫骨内侧缘后方，为肝脾肾三经交会穴。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2495","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"百会穴位于","options":["头顶正中线与两耳尖连线交点","前发际正中直上1寸","后发际正中直上1寸","耳后"],"answer":0,"explanation":"百会穴位于头顶正中线与两耳尖连线的交点处。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2496","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"涌泉穴位于","options":["足底前1/3凹陷处","足背","足跟","足趾"],"answer":0,"explanation":"涌泉穴位于足底第2、3趾缝纹头端与足跟连线的前1/3处。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2497","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"针刺时，病人出现晕针应","options":["继续针刺","立即出针，让病人平卧，饮温水","加大刺激","不留针"],"answer":1,"explanation":"晕针应立即出针，平卧、保暖、饮温水，重者掐人中并抢救。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2498","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"拔罐的主要作用不包括","options":["温补阳气","行气活血","祛风散寒","消肿止痛"],"answer":0,"explanation":"拔罐有行气活血、祛风散寒、消肿止痛等作用，不以温补阳气为主。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2499","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"刮痧的作用不包括","options":["清热解毒","发汗解表","舒筋活络","温阳散寒"],"answer":3,"explanation":"刮痧有发汗解表、舒筋活络、清热解毒等作用，不以温阳散寒为主。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2500","_shard":"qk-yiliao-04"}]);